// Character classification and string helpers.
//
// Everything here works on single Unicode code points represented as JS
// strings, and every predicate is written with explicit comparisons or
// membership sets so that no pattern-matching engine is involved.

/** Split a JS string into an array of code points (astral-safe). */
export function codePoints(text) {
  const out = [];
  for (const ch of text) out.push(ch);
  return out;
}

/** Repeat `ch` `n` times (n <= 0 yields ''). */
export function repeat(ch, n) {
  return n > 0 ? ch.repeat(n) : '';
}

/** Left-pad a decimal string with zeros up to `width`. */
export function zfill(text, width) {
  let s = text;
  let neg = false;
  if (s.startsWith('-')) {
    neg = true;
    s = s.slice(1);
  }
  while (s.length < (neg ? width - 1 : width)) s = '0' + s;
  return (neg ? '-' : '') + s;
}

/** True when `text` contains `ch` (plain scan, used in place of `ch in str`). */
export function inSet(ch, text) {
  return ch !== undefined && ch.length > 0 && text.indexOf(ch) !== -1;
}

export const NULL_BL_LINEBR = '\0 \r\n\x85  ';
export const NULL_BL_T_LINEBR = '\0 \t\r\n\x85  ';
export const NULL_OR_LINEBR = '\0\r\n\x85  ';
export const LINEBR = '\r\n\x85  ';
export const FULL_LINEBR = '\n\x85  ';
export const SPACES_AND_BREAKS = ' \t\r\n\x85  ';

export const DIGITS = '0123456789';
export const HEX_DIGITS = '0123456789abcdefABCDEF';
export const OCT_DIGITS = '01234567';
export const BIN_DIGITS = '01';

export function isDigit(ch) {
  return ch >= '0' && ch <= '9';
}

export function isAsciiLetter(ch) {
  return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z');
}

/** PyYAML `scan_anchor` / `scan_tag_handle` name characters. */
export function isAlphaNumeric(ch) {
  return isDigit(ch) || isAsciiLetter(ch) || ch === '-' || ch === '_';
}

export function isLineBreak(ch) {
  return ch === '\n' || ch === '\x85' || ch === ' ' || ch === ' ';
}

/** Reader's printability rule: the complement of PyYAML's NON_PRINTABLE set. */
export function isPrintableChar(ch) {
  const c = ch.codePointAt(0);
  if (c === 0x09 || c === 0x0a || c === 0x0d) return true;
  if (c >= 0x20 && c <= 0x7e) return true;
  if (c === 0x85) return true;
  if (c >= 0xa0 && c <= 0xd7ff) return true;
  if (c >= 0xe000 && c <= 0xfffd) return true;
  if (c >= 0x10000 && c <= 0x10ffff) return true;
  return false;
}

/**
 * The character class the emitter treats as "printable unicode" when
 * allow_unicode is on: \x85, \xA0-퟿, -�, \U00010000-\U0010FFFE
 * minus ﻿.
 */
export function isEmittableUnicode(ch) {
  const c = ch.codePointAt(0);
  if (c === 0xfeff) return false;
  if (c === 0x85) return true;
  if (c >= 0xa0 && c <= 0xd7ff) return true;
  if (c >= 0xe000 && c <= 0xfffd) return true;
  if (c >= 0x10000 && c < 0x10ffff) return true;
  return false;
}

/** The `\x20 <= ch <= \x7E` test used by write_double_quoted. */
export function isAsciiPrintable(ch) {
  const c = ch.codePointAt(0);
  return c >= 0x20 && c <= 0x7e;
}

