// Error objects mirroring PyYAML's exception hierarchy, plus the small amount
// of Python exception plumbing the entry point needs to reproduce exit codes.

import { repeat } from './chars.mjs';

const SNIPPET_BREAKS = '\0\r\n\x85  ';

export class Mark {
  /**
   * @param {string} name          stream name, always "<unicode string>" here
   * @param {number} index         code point offset in the stream
   * @param {number} line          zero-based line
   * @param {number} column        zero-based column
   * @param {string[]|null} buffer code point array backing the stream
   * @param {number|null} pointer  offset of this mark inside `buffer`
   */
  constructor(name, index, line, column, buffer, pointer) {
    this.name = name;
    this.index = index;
    this.line = line;
    this.column = column;
    this.buffer = buffer;
    this.pointer = pointer;
  }

  getSnippet(indent = 4, maxLength = 75) {
    if (this.buffer === null || this.buffer === undefined) return null;
    let head = '';
    let start = this.pointer;
    while (start > 0 && SNIPPET_BREAKS.indexOf(this.buffer[start - 1]) === -1) {
      start -= 1;
      if (this.pointer - start > maxLength / 2 - 1) {
        head = ' ... ';
        start += 5;
        break;
      }
    }
    let tail = '';
    let end = this.pointer;
    while (end < this.buffer.length && SNIPPET_BREAKS.indexOf(this.buffer[end]) === -1) {
      end += 1;
      if (end - this.pointer > maxLength / 2 - 1) {
        tail = ' ... ';
        end -= 5;
        break;
      }
    }
    const snippet = this.buffer.slice(start, end).join('');
    return (
      repeat(' ', indent) + head + snippet + tail + '\n' +
      repeat(' ', indent + this.pointer - start + head.length) + '^'
    );
  }

  toString() {
    const snippet = this.getSnippet();
    let where = `  in "${this.name}", line ${this.line + 1}, column ${this.column + 1}`;
    if (snippet !== null) where += ':\n' + snippet;
    return where;
  }
}

/** Base class for everything the library raises; `pyName` feeds the traceback. */
export class YAMLError extends Error {
  constructor(message) {
    super(message);
    this.pyName = 'yaml.error.YAMLError';
  }
}

export class MarkedYAMLError extends YAMLError {
  constructor(context, contextMark, problem, problemMark, note) {
    super('');
    this.context = context ?? null;
    this.contextMark = contextMark ?? null;
    this.problem = problem ?? null;
    this.problemMark = problemMark ?? null;
    this.note = note ?? null;
    this.pyName = 'yaml.error.MarkedYAMLError';
    this.message = this.describe();
  }

  describe() {
    const lines = [];
    if (this.context !== null) lines.push(this.context);
    if (
      this.contextMark !== null &&
      (this.problem === null ||
        this.problemMark === null ||
        this.contextMark.name !== this.problemMark.name ||
        this.contextMark.line !== this.problemMark.line ||
        this.contextMark.column !== this.problemMark.column)
    ) {
      lines.push(this.contextMark.toString());
    }
    if (this.problem !== null) lines.push(this.problem);
    if (this.problemMark !== null) lines.push(this.problemMark.toString());
    if (this.note !== null) lines.push(this.note);
    return lines.join('\n');
  }
}

function marked(name) {
  return class extends MarkedYAMLError {
    constructor(context, contextMark, problem, problemMark, note) {
      super(context, contextMark, problem, problemMark, note);
      this.pyName = name;
    }
  };
}

export const ScannerError = marked('yaml.scanner.ScannerError');
export const ParserError = marked('yaml.parser.ParserError');
export const ComposerError = marked('yaml.composer.ComposerError');
export const ConstructorError = marked('yaml.constructor.ConstructorError');

export class ReaderError extends YAMLError {
  constructor(name, position, character, encoding, reason) {
    super('');
    this.name_ = name;
    this.position = position;
    this.character = character;
    this.encoding = encoding;
    this.reason = reason;
    this.pyName = 'yaml.reader.ReaderError';
    this.message =
      `unacceptable character #x${this.character.toString(16).toUpperCase()}: ${reason}\n` +
      `  in "${name}", position ${position}`;
  }
}

export class RepresenterError extends YAMLError {
  constructor(message) {
    super(message);
    this.pyName = 'yaml.representer.RepresenterError';
  }
}

export class EmitterError extends YAMLError {
  constructor(message) {
    super(message);
    this.pyName = 'yaml.emitter.EmitterError';
  }
}

export class SerializerError extends YAMLError {
  constructor(message) {
    super(message);
    this.pyName = 'yaml.serializer.SerializerError';
  }
}

/** Stand-in for the builtin Python exceptions the script can surface. */
export class PythonError extends Error {
  constructor(pyName, message) {
    super(message);
    this.pyName = pyName;
  }
}

export function valueError(message) {
  return new PythonError('ValueError', message);
}

export function typeError(message) {
  return new PythonError('TypeError', message);
}

