// The Python value model.
//
// safe_load has to hand the representer values that behave like Python's, so
// each Python type gets an explicit JS counterpart:
//
//   None -> null            int      -> BigInt        float -> number
//   bool -> boolean         str      -> string        bytes -> PyBytes
//   list -> Array           tuple    -> PyTuple       dict  -> PyDict
//   set  -> PySet           date     -> PyDate        datetime -> PyDateTime

import { zfill } from './chars.mjs';
import { typeError, valueError } from './errors.mjs';
import { floatRepr } from './pyfloat.mjs';

export class PyBytes {
  constructor(bytes) {
    this.bytes = bytes; // Uint8Array
  }
}

export class PyTuple {
  constructor(items) {
    this.items = items;
  }
}

export class PyTimezone {
  /** @param {number} minutes signed offset from UTC */
  constructor(minutes) {
    if (minutes <= -1440 || minutes >= 1440) {
      throw valueError(
        'offset must be a timedelta strictly between -timedelta(hours=24) and timedelta(hours=24)'
      );
    }
    this.minutes = minutes;
  }

  static utc() {
    return new PyTimezone(0);
  }

  /** `+HH:MM` as datetime.isoformat renders it. */
  isoformat() {
    const sign = this.minutes < 0 ? '-' : '+';
    const abs = Math.abs(this.minutes);
    return sign + zfill(String(Math.floor(abs / 60)), 2) + ':' + zfill(String(abs % 60), 2);
  }
}

const MONTH_DAYS = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

function isLeap(year) {
  return year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
}

export function daysInMonth(year, month) {
  if (month === 2 && isLeap(year)) return 29;
  return MONTH_DAYS[month - 1];
}

function checkDateParts(year, month, day) {
  if (year < 1 || year > 9999) throw valueError(`year ${year} is out of range`);
  if (month < 1 || month > 12) throw valueError('month must be in 1..12');
  if (day < 1 || day > daysInMonth(year, month)) {
    throw valueError('day is out of range for month');
  }
}

function checkTimeParts(hour, minute, second, microsecond) {
  if (hour < 0 || hour > 23) throw valueError('hour must be in 0..23');
  if (minute < 0 || minute > 59) throw valueError('minute must be in 0..59');
  if (second < 0 || second > 59) throw valueError('second must be in 0..59');
  if (microsecond < 0 || microsecond > 999999) {
    throw valueError('microsecond must be in 0..999999');
  }
}

export class PyDate {
  constructor(year, month, day) {
    checkDateParts(year, month, day);
    this.year = year;
    this.month = month;
    this.day = day;
  }

  /** Days since a fixed epoch; only used for ordering. */
  toOrdinal() {
    let y = this.year;
    let total = 365 * (y - 1) + Math.floor((y - 1) / 4) - Math.floor((y - 1) / 100) +
      Math.floor((y - 1) / 400);
    for (let m = 1; m < this.month; m++) total += daysInMonth(y, m);
    return total + this.day;
  }

  isoformat() {
    return (
      zfill(String(this.year), 4) + '-' + zfill(String(this.month), 2) + '-' +
      zfill(String(this.day), 2)
    );
  }
}

export class PyDateTime {
  constructor(year, month, day, hour, minute, second, microsecond, tzinfo) {
    checkDateParts(year, month, day);
    checkTimeParts(hour, minute, second, microsecond);
    this.year = year;
    this.month = month;
    this.day = day;
    this.hour = hour;
    this.minute = minute;
    this.second = second;
    this.microsecond = microsecond;
    this.tzinfo = tzinfo ?? null;
  }

  isoformat(sep = 'T') {
    const date = new PyDate(this.year, this.month, this.day).isoformat();
    let time =
      zfill(String(this.hour), 2) + ':' + zfill(String(this.minute), 2) + ':' +
      zfill(String(this.second), 2);
    if (this.microsecond) time += '.' + zfill(String(this.microsecond), 6);
    let out = date + sep + time;
    if (this.tzinfo !== null) out += this.tzinfo.isoformat();
    return out;
  }

  /** Minutes since epoch (UTC-normalised when aware); only used for ordering. */
  toComparable() {
    const date = new PyDate(this.year, this.month, this.day);
    let minutes = date.toOrdinal() * 1440 + this.hour * 60 + this.minute;
    if (this.tzinfo !== null) minutes -= this.tzinfo.minutes;
    return minutes * 60e6 + this.second * 1e6 + this.microsecond;
  }
}

/* ------------------------------------------------------------------ */
/* Hashing / equality                                                  */
/* ------------------------------------------------------------------ */

/**
 * Canonical dict-key string. Python's numeric tower makes `1`, `1.0` and
 * `True` the same key, so all three collapse onto one representation.
 */
export function hashKey(value) {
  if (value === null) return 'N';
  const t = typeof value;
  if (t === 'boolean') return 'n:' + (value ? '1' : '0');
  if (t === 'bigint') return 'n:' + value.toString();
  if (t === 'number') {
    if (Number.isNaN(value)) return 'n:nan';
    if (value === Infinity) return 'n:inf';
    if (value === -Infinity) return 'n:-inf';
    if (Number.isInteger(value)) return 'n:' + BigInt(value).toString();
    return 'n:' + floatRepr(value);
  }
  if (t === 'string') return 's:' + value;
  if (value instanceof PyBytes) {
    let hex = '';
    for (const b of value.bytes) hex += zfill(b.toString(16), 2);
    return 'b:' + hex;
  }
  if (value instanceof PyTuple) {
    return 't:(' + value.items.map((item) => hashKey(item)).join(',') + ')';
  }
  if (value instanceof PyDate) return 'd:' + value.isoformat();
  if (value instanceof PyDateTime) return 'dt:' + value.isoformat();
  if (value instanceof PyFrozenSet) {
    return 'fs:{' + value.keys().map((k) => hashKey(k)).sort().join(',') + '}';
  }
  if (Array.isArray(value)) throw typeError("unhashable type: 'list'");
  if (value instanceof PyDict) throw typeError("unhashable type: 'dict'");
  if (value instanceof PySet) throw typeError("unhashable type: 'set'");
  throw typeError('unhashable type');
}

export function pyEqual(a, b) {
  try {
    return hashKey(a) === hashKey(b);
  } catch {
    return a === b;
  }
}

/* ------------------------------------------------------------------ */
/* Containers                                                          */
/* ------------------------------------------------------------------ */

/** Insertion-ordered mapping with Python key semantics. */
export class PyDict {
  constructor() {
    this._index = new Map(); // hash -> slot
    this._order = []; // slots in insertion order
  }

  get size() {
    return this._order.length;
  }

  has(key) {
    return this._index.has(hashKey(key));
  }

  get(key) {
    const slot = this._index.get(hashKey(key));
    return slot === undefined ? undefined : slot.value;
  }

  /** Python semantics: an existing key keeps its object and position. */
  set(key, value) {
    const h = hashKey(key);
    const slot = this._index.get(h);
    if (slot !== undefined) {
      slot.value = value;
      return;
    }
    const fresh = { key, value };
    this._index.set(h, fresh);
    this._order.push(fresh);
  }

  items() {
    return this._order.map((slot) => [slot.key, slot.value]);
