// Numeric formatting and parsing that follows CPython rather than JS.

import { valueError } from './errors.mjs';
import { DIGITS, HEX_DIGITS, isDigit } from './chars.mjs';

/**
 * CPython's `repr(float)`: shortest round-tripping digits, rendered in fixed
 * notation unless the decimal point lands outside (-4, 16].
 */
export function floatRepr(value) {
  if (Number.isNaN(value)) return 'nan';
  if (value === Infinity) return 'inf';
  if (value === -Infinity) return '-inf';

  const negative = value < 0 || Object.is(value, -0);
  const abs = negative ? -value : value;
  if (abs === 0) return negative ? '-0.0' : '0.0';

  // toExponential() with no argument yields the shortest digit string that
  // round-trips, which is exactly what repr() needs.
  const text = abs.toExponential();
  const eIndex = text.indexOf('e');
  let mantissa = text.slice(0, eIndex);
  const exponent = Number(text.slice(eIndex + 1));
  const dot = mantissa.indexOf('.');
  if (dot !== -1) mantissa = mantissa.slice(0, dot) + mantissa.slice(dot + 1);

  const decpt = exponent + 1; // value == 0.<mantissa> * 10**decpt
  let out;
  if (decpt <= -4 || decpt > 16) {
    out = mantissa[0];
    if (mantissa.length > 1) out += '.' + mantissa.slice(1);
    const e = decpt - 1;
    let digits = String(Math.abs(e));
    if (digits.length < 2) digits = '0' + digits;
    out += 'e' + (e < 0 ? '-' : '+') + digits;
  } else if (decpt <= 0) {
    out = '0.' + '0'.repeat(-decpt) + mantissa;
  } else if (decpt >= mantissa.length) {
    out = mantissa + '0'.repeat(decpt - mantissa.length) + '.0';
  } else {
    out = mantissa.slice(0, decpt) + '.' + mantissa.slice(decpt);
  }
  return (negative ? '-' : '') + out;
}

/** Python's `float(str)` for the forms YAML can produce. */
export function parseFloat_(text) {
  const raw = text.trim();
  if (raw.length === 0) throw valueError(`could not convert string to float: '${text}'`);
  let index = 0;
  let sign = 1;
  if (raw[index] === '+' || raw[index] === '-') {
    if (raw[index] === '-') sign = -1;
    index += 1;
  }
  const rest = raw.slice(index).toLowerCase();
  if (rest === 'inf' || rest === 'infinity') return sign * Infinity;
  if (rest === 'nan') return sign * NaN;

  let intDigits = 0;
  let fracDigits = 0;
  while (index < raw.length && isDigit(raw[index])) {
    index += 1;
    intDigits += 1;
  }
  if (raw[index] === '.') {
    index += 1;
    while (index < raw.length && isDigit(raw[index])) {
      index += 1;
      fracDigits += 1;
    }
  }
  if (intDigits + fracDigits === 0) {
    throw valueError(`could not convert string to float: '${text}'`);
  }
  if (raw[index] === 'e' || raw[index] === 'E') {
    index += 1;
    if (raw[index] === '+' || raw[index] === '-') index += 1;
    let expDigits = 0;
    while (index < raw.length && isDigit(raw[index])) {
      index += 1;
      expDigits += 1;
    }
    if (expDigits === 0) throw valueError(`could not convert string to float: '${text}'`);
  }
  if (index !== raw.length) throw valueError(`could not convert string to float: '${text}'`);
  return sign * Number(raw.slice(raw[0] === '+' || raw[0] === '-' ? 1 : 0));
}

const BASE_PREFIX = { 2: 'b', 8: 'o', 16: 'x' };

/** Python's `int(str, base)` returning a BigInt. */
export function parseInt_(text, base = 10) {
  let raw = text.trim();
  const original = text;
  let sign = 1n;
  if (raw[0] === '+' || raw[0] === '-') {
    if (raw[0] === '-') sign = -1n;
    raw = raw.slice(1);
  }
  const prefix = BASE_PREFIX[base];
  if (prefix !== undefined && raw.length > 2 && raw[0] === '0' &&
      raw[1].toLowerCase() === prefix) {
    raw = raw.slice(2);
  }
  if (raw.length === 0) {
    throw valueError(`invalid literal for int() with base ${base}: '${original}'`);
  }
  const bigBase = BigInt(base);
  let total = 0n;
  for (const ch of raw) {
    const digit = HEX_DIGITS.indexOf(ch.toLowerCase());
    if (digit === -1 || digit >= base) {
      throw valueError(`invalid literal for int() with base ${base}: '${original}'`);
    }
    total = total * bigBase + BigInt(digit);
  }
  return sign * total;
}

/** True when every character is a decimal digit and there is at least one. */
export function allDigits(text) {
  if (text.length === 0) return false;
  for (const ch of text) {
    if (DIGITS.indexOf(ch) === -1) return false;
  }
  return true;
}

