// Base64, matching what PyYAML relies on from the Python stdlib:
// `binascii.a2b_base64` for loading and `base64.encodebytes` (76-column
// wrapped) for dumping.

import { valueError } from './errors.mjs';

const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

const REVERSE = (() => {
  const table = new Int8Array(128).fill(-1);
  for (let i = 0; i < ALPHABET.length; i++) table[ALPHABET.charCodeAt(i)] = i;
  return table;
})();

/** Decode, ignoring characters outside the alphabet the way binascii does. */
export function base64Decode(text) {
  const values = [];
  for (const ch of text) {
    const code = ch.codePointAt(0);
    if (ch === '=') break;
    if (code < 128 && REVERSE[code] !== -1) values.push(REVERSE[code]);
  }
  if (values.length % 4 === 1) throw valueError('Invalid base64-encoded string');
  const out = [];
  for (let i = 0; i + 1 < values.length; i += 4) {
    const chunk = values.slice(i, i + 4);
    const bits = chunk.length;
    let acc = 0;
    for (let j = 0; j < 4; j++) acc = (acc << 6) | (j < bits ? chunk[j] : 0);
    out.push((acc >> 16) & 0xff);
    if (bits >= 3) out.push((acc >> 8) & 0xff);
    if (bits >= 4) out.push(acc & 0xff);
  }
  return new Uint8Array(out);
}

/** Encode with a trailing newline every 57 input bytes (76 output columns). */
export function base64Encode(bytes, lineLength = 76) {
  let all = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const b0 = bytes[i];
    const b1 = i + 1 < bytes.length ? bytes[i + 1] : 0;
    const b2 = i + 2 < bytes.length ? bytes[i + 2] : 0;
    const acc = (b0 << 16) | (b1 << 8) | b2;
    all += ALPHABET[(acc >> 18) & 63];
    all += ALPHABET[(acc >> 12) & 63];
    all += i + 1 < bytes.length ? ALPHABET[(acc >> 6) & 63] : '=';
    all += i + 2 < bytes.length ? ALPHABET[acc & 63] : '=';
  }
  let out = '';
  for (let i = 0; i < all.length; i += lineLength) {
    out += all.slice(i, i + lineLength) + '\n';
  }
  return out;
}

/** UTF-8 encode a JS string into bytes (used by the !!binary loader). */
export function utf8Encode(text) {
  return new Uint8Array(Buffer.from(text, 'utf8'));
}

/** UTF-8 decode bytes; mirrors `bytes.decode('utf-8')`. */
export function utf8Decode(bytes) {
  return Buffer.from(bytes).toString('utf8');
}

/** Latin-1 decode, the encoding PyYAML uses to re-read !!binary payloads. */
export function latin1Encode(text) {
  const out = new Uint8Array(text.length);
  for (let i = 0; i < text.length; i++) out[i] = text.charCodeAt(i) & 0xff;
  return out;
}

