// Implicit type resolution — the tag a plain scalar gets when none is written.
//
// PyYAML drives this with compiled regexes; here each pattern is a hand-rolled
// matcher over the characters of the scalar.

import { ScalarNode, SequenceNode, MappingNode } from './events.mjs';
import { DIGITS, HEX_DIGITS, isDigit } from './chars.mjs';

/** Cursor over a scalar, offering just enough to express the YAML patterns. */
class Cursor {
  constructor(text) {
    this.text = text;
    this.pos = 0;
  }

  get done() {
    return this.pos >= this.text.length;
  }

  peek(offset = 0) {
    const index = this.pos + offset;
    return index < this.text.length ? this.text[index] : '';
  }

  accept(chars) {
    if (!this.done && chars.indexOf(this.text[this.pos]) !== -1) {
      this.pos += 1;
      return true;
    }
    return false;
  }

  acceptRun(chars) {
    let count = 0;
    while (this.accept(chars)) count += 1;
    return count;
  }

  acceptLiteral(literal) {
    if (this.text.startsWith(literal, this.pos)) {
      this.pos += literal.length;
      return true;
    }
    return false;
  }
}

const DIGITS_UNDERSCORE = DIGITS + '_';
const HEX_UNDERSCORE = HEX_DIGITS + '_';

/** `(?::[0-5]?[0-9])+` — one or more sexagesimal groups. */
function acceptSexagesimalGroups(cursor) {
  let groups = 0;
  while (cursor.peek() === ':') {
    const save = cursor.pos;
    cursor.pos += 1;
    const first = cursor.peek();
    if (!isDigit(first)) {
      cursor.pos = save;
      break;
    }
    // Greedy two digits when the leading one is 0-5; a single-digit group can
    // only work when the next character already terminates the group, so no
    // backtracking is needed.
    if (first >= '0' && first <= '5' && isDigit(cursor.peek(1))) cursor.pos += 2;
    else cursor.pos += 1;
    groups += 1;
  }
  return groups;
}

function matchesFloat(value) {
  // [-+]?[0-9][0-9_]*\.[0-9_]*(?:[eE][-+][0-9]+)?
  {
    const c = new Cursor(value);
    c.accept('-+');
    if (isDigit(c.peek())) {
      c.pos += 1;
      c.acceptRun(DIGITS_UNDERSCORE);
      if (c.accept('.')) {
        c.acceptRun(DIGITS_UNDERSCORE);
        if (c.done) return true;
        if (c.accept('eE') && c.accept('-+') && c.acceptRun(DIGITS) > 0 && c.done) return true;
      }
    }
  }
  // \.[0-9][0-9_]*(?:[eE][-+][0-9]+)?
  {
    const c = new Cursor(value);
    if (c.accept('.') && isDigit(c.peek())) {
      c.pos += 1;
      c.acceptRun(DIGITS_UNDERSCORE);
      if (c.done) return true;
      if (c.accept('eE') && c.accept('-+') && c.acceptRun(DIGITS) > 0 && c.done) return true;
    }
  }
  // [-+]?[0-9][0-9_]*(?::[0-5]?[0-9])+\.[0-9_]*
  {
    const c = new Cursor(value);
    c.accept('-+');
    if (isDigit(c.peek())) {
      c.pos += 1;
      c.acceptRun(DIGITS_UNDERSCORE);
      if (acceptSexagesimalGroups(c) > 0 && c.accept('.')) {
        c.acceptRun(DIGITS_UNDERSCORE);
        if (c.done) return true;
      }
    }
  }
  // [-+]?\.(?:inf|Inf|INF)
  {
    const c = new Cursor(value);
    c.accept('-+');
    if (c.accept('.')) {
      for (const word of ['inf', 'Inf', 'INF']) {
        const save = c.pos;
        if (c.acceptLiteral(word) && c.done) return true;
        c.pos = save;
      }
    }
  }
  // \.(?:nan|NaN|NAN)
