// Stream reader. The buffer is an array of code points so that column numbers
// and marks count characters the way Python does.

import { Mark, ReaderError } from './errors.mjs';
import { Resolver } from './resolver.mjs';
import { codePoints, isPrintableChar } from './chars.mjs';

export class Reader extends Resolver {
  initReader(text) {
    this.name = '<unicode string>';
    this.index = 0;
    this.line = 0;
    this.column = 0;
    this.checkPrintable(text);
    this.buffer = codePoints(text);
    this.buffer.push('\0');
    this.pointer = 0;
  }

  checkPrintable(text) {
    let position = 0;
    for (const ch of text) {
      if (!isPrintableChar(ch)) {
        throw new ReaderError(
          '<unicode string>', position, ch.codePointAt(0), 'unicode',
          'special characters are not allowed'
        );
      }
      position += 1;
    }
  }

  peek(index = 0) {
    const ch = this.buffer[this.pointer + index];
    return ch === undefined ? '\0' : ch;
  }

  prefix(length = 1) {
    return this.buffer.slice(this.pointer, this.pointer + length).join('');
  }

  forward(length = 1) {
    let remaining = length;
    while (remaining > 0) {
      const ch = this.buffer[this.pointer];
      this.pointer += 1;
      this.index += 1;
      if (
        ch === '\n' || ch === '\x85' || ch === ' ' || ch === ' ' ||
        (ch === '\r' && this.buffer[this.pointer] !== '\n')
      ) {
        this.line += 1;
        this.column = 0;
      } else if (ch !== '﻿') {
        this.column += 1;
      }
      remaining -= 1;
    }
  }

  getMark() {
    return new Mark(this.name, this.index, this.line, this.column, this.buffer, this.pointer);
  }
}

