import { ScannerError } from './errors.mjs';
import { inSet } from './chars.mjs';
import {
  AliasToken, AnchorToken, BlockEndToken, BlockEntryToken,
  BlockMappingStartToken, BlockSequenceStartToken, DirectiveToken,
  DocumentEndToken, DocumentStartToken, FlowEntryToken, FlowMappingEndToken,
  FlowMappingStartToken, FlowSequenceEndToken, FlowSequenceStartToken,
  KeyToken, ScalarToken, StreamEndToken, StreamStartToken, TagToken, ValueToken,
} from './tokens.mjs';

const NULL_BL_T_LINEBR = '\0 \t\r\n\x85  ';
const NULL_BL_LINEBR = '\0 \r\n\x85  ';
const NULL_OR_LINEBR = '\0\r\n\x85  ';
const LINEBR = '\r\n\x85  ';
const ALPHA_EXTRA = '-_';
const HEXDIGITS = '0123456789ABCDEFabcdef';

/** Python's `repr()` for the single characters that appear in scanner errors. */
export function charRepr(ch) {
  const map = {
    '\\': '\\\\', "'": "\\'", '\n': '\\n', '\r': '\\r', '\t': '\\t',
    '\x07': '\\x07', '\x08': '\\x08', '\x0b': '\\x0b', '\x0c': '\\x0c',
    '\0': '\\x00', '\x1b': '\\x1b', '\x85': '\\x85',
  };
  if (map[ch] !== undefined) return "'" + map[ch] + "'";
  const code = ch.codePointAt(0);
  if (code < 0x20 || code === 0x7f) {
    return "'\\x" + code.toString(16).padStart(2, '0') + "'";
  }
  return "'" + ch + "'";
}

function isNameChar(ch) {
  return (
    (ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z') ||
    ALPHA_EXTRA.indexOf(ch) !== -1
  );
}

class SimpleKey {
  constructor(tokenNumber, required, index, line, column, mark) {
    this.tokenNumber = tokenNumber;
    this.required = required;
    this.index = index;
    this.line = line;
    this.column = column;
    this.mark = mark;
  }
}

