// Tokenizer. A direct port of PyYAML's scanner, including its simple-key
// bookkeeping and its deliberate deviations from the spec.

import { Reader } from './reader.mjs';
import { ScannerError } from './errors.mjs';
import { inSet } from './chars.mjs';
import {
  AliasToken, AnchorToken, BlockEndToken, BlockEntryToken,
  BlockMappingStartToken, BlockSequenceStartToken, DirectiveToken,
  DocumentEndToken, DocumentStartToken, FlowEntryToken, FlowMappingEndToken,
  FlowMappingStartToken, FlowSequenceEndToken, FlowSequenceStartToken,
  KeyToken, ScalarToken, StreamEndToken, StreamStartToken, TagToken, ValueToken,
} from './tokens.mjs';

const NULL_BL_T_LINEBR = '\0 \t\r\n\x85  ';
const NULL_BL_LINEBR = '\0 \r\n\x85  ';
const NULL_OR_LINEBR = '\0\r\n\x85  ';
const LINEBR = '\r\n\x85  ';
const ALPHA_EXTRA = '-_';
const HEXDIGITS = '0123456789ABCDEFabcdef';

/** Python's `repr()` for the single characters that appear in scanner errors. */
export function charRepr(ch) {
  const map = {
    '\\': '\\\\', "'": "\\'", '\n': '\\n', '\r': '\\r', '\t': '\\t',
    '\x07': '\\x07', '\x08': '\\x08', '\x0b': '\\x0b', '\x0c': '\\x0c',
    '\0': '\\x00', '\x1b': '\\x1b', '\x85': '\\x85',
  };
  if (map[ch] !== undefined) return "'" + map[ch] + "'";
  const code = ch.codePointAt(0);
  if (code < 0x20 || code === 0x7f) {
    return "'\\x" + code.toString(16).padStart(2, '0') + "'";
  }
  return "'" + ch + "'";
}

function isNameChar(ch) {
  return (
    (ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z') ||
    ALPHA_EXTRA.indexOf(ch) !== -1
  );
}

class SimpleKey {
  constructor(tokenNumber, required, index, line, column, mark) {
    this.tokenNumber = tokenNumber;
    this.required = required;
    this.index = index;
    this.line = line;
    this.column = column;
    this.mark = mark;
  }
}

export class Scanner extends Reader {
  initScanner() {
    this.done = false;
    this.flowLevel = 0;
    this.tokens = [];
    this.encoding = null;
    this.fetchStreamStart();
    this.tokensTaken = 0;
    this.indent = -1;
    this.indents = [];
    this.allowSimpleKey = true;
    this.possibleSimpleKeys = new Map();
  }

  /** @param {Function[]} choices token classes; empty means "any token" */
  checkToken(...choices) {
    while (this.needMoreTokens()) this.fetchMoreTokens();
    if (this.tokens.length > 0) {
      if (choices.length === 0) return true;
      for (const choice of choices) {
        if (this.tokens[0] instanceof choice) return true;
      }
    }
    return false;
  }

  peekToken() {
    while (this.needMoreTokens()) this.fetchMoreTokens();
    return this.tokens.length > 0 ? this.tokens[0] : null;
  }

  getToken() {
    while (this.needMoreTokens()) this.fetchMoreTokens();
    if (this.tokens.length > 0) {
      this.tokensTaken += 1;
      return this.tokens.shift();
    }
    return null;
  }

  needMoreTokens() {
    if (this.done) return false;
    if (this.tokens.length === 0) return true;
    this.stalePossibleSimpleKeys();
    return this.nextPossibleSimpleKey() === this.tokensTaken;
  }

  fetchMoreTokens() {
    this.scanToNextToken();
    this.stalePossibleSimpleKeys();
    this.unwindIndent(this.column);

    const ch = this.peek();

    if (ch === '\0') return this.fetchStreamEnd();
    if (ch === '%' && this.checkDirective()) return this.fetchDirective();
    if (ch === '-' && this.checkDocumentStart()) return this.fetchDocumentStart();
    if (ch === '.' && this.checkDocumentEnd()) return this.fetchDocumentEnd();
    if (ch === '[') return this.fetchFlowSequenceStart();
    if (ch === '{') return this.fetchFlowMappingStart();
    if (ch === ']') return this.fetchFlowSequenceEnd();
    if (ch === '}') return this.fetchFlowMappingEnd();
    if (ch === ',') return this.fetchFlowEntry();
    if (ch === '-' && this.checkBlockEntry()) return this.fetchBlockEntry();
    if (ch === '?' && this.checkKey()) return this.fetchKey();
    if (ch === ':' && this.checkValue()) return this.fetchValue();
    if (ch === '*') return this.fetchAlias();
    if (ch === '&') return this.fetchAnchor();
    if (ch === '!') return this.fetchTag();
    if (ch === '|' && !this.flowLevel) return this.fetchLiteral();
    if (ch === '>' && !this.flowLevel) return this.fetchFolded();
    if (ch === "'") return this.fetchSingle();
    if (ch === '"') return this.fetchDouble();
    if (this.checkPlain()) return this.fetchPlain();

    throw new ScannerError(
      'while scanning for the next token', null,
      `found character ${charRepr(ch)} that cannot start any token`, this.getMark()
    );
  }

  /* -------------------------------------------------------------- */
  /* Simple keys                                                     */
  /* -------------------------------------------------------------- */

  nextPossibleSimpleKey() {
    let minTokenNumber = null;
    for (const key of this.possibleSimpleKeys.values()) {
      if (minTokenNumber === null || key.tokenNumber < minTokenNumber) {
        minTokenNumber = key.tokenNumber;
      }
    }
    return minTokenNumber;
  }

  stalePossibleSimpleKeys() {
    for (const level of Array.from(this.possibleSimpleKeys.keys())) {
      const key = this.possibleSimpleKeys.get(level);
      if (key.line !== this.line || this.index - key.index > 1024) {
        if (key.required) {
          throw new ScannerError(
            'while scanning a simple key', key.mark,
            "could not find expected ':'", this.getMark()
          );
        }
        this.possibleSimpleKeys.delete(level);
      }
    }
  }

  savePossibleSimpleKey() {
    const required = !this.flowLevel && this.indent === this.column;
    if (this.allowSimpleKey) {
      this.removePossibleSimpleKey();
      const tokenNumber = this.tokensTaken + this.tokens.length;
      this.possibleSimpleKeys.set(
        this.flowLevel,
        new SimpleKey(tokenNumber, required, this.index, this.line, this.column, this.getMark())
      );
    }
  }

  removePossibleSimpleKey() {
    const key = this.possibleSimpleKeys.get(this.flowLevel);
    if (key !== undefined) {
      if (key.required) {
        throw new ScannerError(
          'while scanning a simple key', key.mark,
          "could not find expected ':'", this.getMark()
        );
      }
      this.possibleSimpleKeys.delete(this.flowLevel);
    }
  }

  /* -------------------------------------------------------------- */
  /* Indentation                                                     */
  /* -------------------------------------------------------------- */

  unwindIndent(column) {
    if (this.flowLevel) return;
    while (this.indent > column) {
      const mark = this.getMark();
      this.indent = this.indents.pop();
      this.tokens.push(new BlockEndToken(mark, mark));
    }
  }

  addIndent(column) {
    if (this.indent < column) {
      this.indents.push(this.indent);
      this.indent = column;
      return true;
    }
    return false;
  }

  /* -------------------------------------------------------------- */
  /* Fetchers                                                        */
  /* -------------------------------------------------------------- */

  fetchStreamStart() {
    const mark = this.getMark();
    this.tokens.push(new StreamStartToken(mark, mark, this.encoding));
  }

  fetchStreamEnd() {
    this.unwindIndent(-1);
    this.removePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.possibleSimpleKeys = new Map();
    const mark = this.getMark();
    this.tokens.push(new StreamEndToken(mark, mark));
    this.done = true;
  }

  fetchDirective() {
    this.unwindIndent(-1);
    this.removePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanDirective());
  }

  fetchDocumentStart() {
    this.fetchDocumentIndicator(DocumentStartToken);
  }

  fetchDocumentEnd() {
    this.fetchDocumentIndicator(DocumentEndToken);
  }

  fetchDocumentIndicator(TokenClass) {
    this.unwindIndent(-1);
    this.removePossibleSimpleKey();
    this.allowSimpleKey = false;
    const startMark = this.getMark();
    this.forward(3);
    this.tokens.push(new TokenClass(startMark, this.getMark()));
  }

  fetchFlowSequenceStart() {
    this.fetchFlowCollectionStart(FlowSequenceStartToken);
  }

  fetchFlowMappingStart() {
    this.fetchFlowCollectionStart(FlowMappingStartToken);
  }

  fetchFlowCollectionStart(TokenClass) {
    this.savePossibleSimpleKey();
    this.flowLevel += 1;
    this.allowSimpleKey = true;
    const startMark = this.getMark();
    this.forward();
    this.tokens.push(new TokenClass(startMark, this.getMark()));
  }

  fetchFlowSequenceEnd() {
    this.fetchFlowCollectionEnd(FlowSequenceEndToken);
  }

  fetchFlowMappingEnd() {
    this.fetchFlowCollectionEnd(FlowMappingEndToken);
  }

  fetchFlowCollectionEnd(TokenClass) {
    this.removePossibleSimpleKey();
    this.flowLevel -= 1;
    this.allowSimpleKey = false;
    const startMark = this.getMark();
    this.forward();
    this.tokens.push(new TokenClass(startMark, this.getMark()));
  }

  fetchFlowEntry() {
    this.allowSimpleKey = true;
    this.removePossibleSimpleKey();
    const startMark = this.getMark();
    this.forward();
    this.tokens.push(new FlowEntryToken(startMark, this.getMark()));
  }

  fetchBlockEntry() {
    if (!this.flowLevel) {
      if (!this.allowSimpleKey) {
        throw new ScannerError(
          null, null, 'sequence entries are not allowed here', this.getMark()
        );
      }
      if (this.addIndent(this.column)) {
        const mark = this.getMark();
        this.tokens.push(new BlockSequenceStartToken(mark, mark));
      }
    }
    this.allowSimpleKey = true;
    this.removePossibleSimpleKey();
    const startMark = this.getMark();
    this.forward();
    this.tokens.push(new BlockEntryToken(startMark, this.getMark()));
  }

  fetchKey() {
    if (!this.flowLevel) {
      if (!this.allowSimpleKey) {
        throw new ScannerError(
          null, null, 'mapping keys are not allowed here', this.getMark()
        );
      }
      if (this.addIndent(this.column)) {
        const mark = this.getMark();
        this.tokens.push(new BlockMappingStartToken(mark, mark));
      }
    }
    this.allowSimpleKey = !this.flowLevel;
    this.removePossibleSimpleKey();
    const startMark = this.getMark();
    this.forward();
    this.tokens.push(new KeyToken(startMark, this.getMark()));
  }

  fetchValue() {
    const key = this.possibleSimpleKeys.get(this.flowLevel);
    if (key !== undefined) {
      this.possibleSimpleKeys.delete(this.flowLevel);
      this.tokens.splice(key.tokenNumber - this.tokensTaken, 0, new KeyToken(key.mark, key.mark));
      if (!this.flowLevel && this.addIndent(key.column)) {
        this.tokens.splice(
          key.tokenNumber - this.tokensTaken, 0,
          new BlockMappingStartToken(key.mark, key.mark)
        );
      }
      this.allowSimpleKey = false;
    } else {
      if (!this.flowLevel && !this.allowSimpleKey) {
        throw new ScannerError(
          null, null, 'mapping values are not allowed here', this.getMark()
        );
      }
      if (!this.flowLevel && this.addIndent(this.column)) {
        const mark = this.getMark();
        this.tokens.push(new BlockMappingStartToken(mark, mark));
      }
      this.allowSimpleKey = !this.flowLevel;
      this.removePossibleSimpleKey();
    }
    const startMark = this.getMark();
    this.forward();
    this.tokens.push(new ValueToken(startMark, this.getMark()));
  }

  fetchAlias() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanAnchor(AliasToken));
  }

  fetchAnchor() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanAnchor(AnchorToken));
  }

  fetchTag() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanTag());
  }

  fetchLiteral() {
    this.fetchBlockScalar('|');
  }

  fetchFolded() {
    this.fetchBlockScalar('>');
  }

  fetchBlockScalar(style) {
    this.allowSimpleKey = true;
    this.removePossibleSimpleKey();
    this.tokens.push(this.scanBlockScalar(style));
  }

  fetchSingle() {
    this.fetchFlowScalar("'");
  }

  fetchDouble() {
    this.fetchFlowScalar('"');
  }

  fetchFlowScalar(style) {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanFlowScalar(style));
  }

  fetchPlain() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanPlain());
  }

  /* -------------------------------------------------------------- */
  /* Checkers                                                        */
  /* -------------------------------------------------------------- */

  checkDirective() {
    return this.column === 0;
  }

  checkDocumentStart() {
    return this.column === 0 && this.prefix(3) === '---' &&
      inSet(this.peek(3), NULL_BL_T_LINEBR);
  }

  checkDocumentEnd() {
    return this.column === 0 && this.prefix(3) === '...' &&
      inSet(this.peek(3), NULL_BL_T_LINEBR);
  }

  checkBlockEntry() {
    return inSet(this.peek(1), NULL_BL_T_LINEBR);
  }

  checkKey() {
    if (this.flowLevel) return true;
    return inSet(this.peek(1), NULL_BL_T_LINEBR);
  }

  checkValue() {
    if (this.flowLevel) return true;
    return inSet(this.peek(1), NULL_BL_T_LINEBR);
  }

  checkPlain() {
    const ch = this.peek();
    return (
      !inSet(ch, NULL_BL_T_LINEBR + '-?:,[]{}#&*!|>\'"%@`') ||
      (!inSet(this.peek(1), NULL_BL_T_LINEBR) &&
        (ch === '-' || (!this.flowLevel && (ch === '?' || ch === ':'))))
    );
  }

  /* -------------------------------------------------------------- */
  /* Scanners                                                        */
  /* -------------------------------------------------------------- */

  scanToNextToken() {
    if (this.index === 0 && this.peek() === '﻿') this.forward();
    let found = false;
    while (!found) {
      while (this.peek() === ' ') this.forward();
      if (this.peek() === '#') {
        while (!inSet(this.peek(), NULL_OR_LINEBR)) this.forward();
      }
      if (this.scanLineBreak() !== '') {
        if (!this.flowLevel) this.allowSimpleKey = true;
      } else {
        found = true;
      }
    }
  }

  scanDirective() {
    const startMark = this.getMark();
    this.forward();
    const name = this.scanDirectiveName(startMark);
    let value = null;
    let endMark;
    if (name === 'YAML') {
      value = this.scanYamlDirectiveValue(startMark);
      endMark = this.getMark();
    } else if (name === 'TAG') {
      value = this.scanTagDirectiveValue(startMark);
      endMark = this.getMark();
    } else {
      endMark = this.getMark();
      while (!inSet(this.peek(), NULL_OR_LINEBR)) this.forward();
    }
    this.scanDirectiveIgnoredLine(startMark);
    return new DirectiveToken(name, value, startMark, endMark);
  }

  scanDirectiveName(startMark) {
    let length = 0;
    let ch = this.peek(length);
    while (isNameChar(ch)) {
      length += 1;
      ch = this.peek(length);
    }
    if (length === 0) {
      throw new ScannerError(
        'while scanning a directive', startMark,
        `expected alphabetic or numeric character, but found ${charRepr(ch)}`, this.getMark()
      );
    }
    const value = this.prefix(length);
    this.forward(length);
    ch = this.peek();
    if (!inSet(ch, NULL_BL_LINEBR)) {
      throw new ScannerError(
        'while scanning a directive', startMark,
        `expected alphabetic or numeric character, but found ${charRepr(ch)}`, this.getMark()
      );
    }
    return value;
  }

  scanYamlDirectiveValue(startMark) {
    while (this.peek() === ' ') this.forward();
    const major = this.scanYamlDirectiveNumber(startMark);
    if (this.peek() !== '.') {
      throw new ScannerError(
        'while scanning a directive', startMark,
        `expected a digit or '.', but found ${charRepr(this.peek())}`, this.getMark()
      );
    }
    this.forward();
    const minor = this.scanYamlDirectiveNumber(startMark);
    if (!inSet(this.peek(), NULL_BL_LINEBR)) {
      throw new ScannerError(
        'while scanning a directive', startMark,
        `expected a digit or ' ', but found ${charRepr(this.peek())}`, this.getMark()
      );
    }
    return [major, minor];
  }

  scanYamlDirectiveNumber(startMark) {
    let ch = this.peek();
    if (!(ch >= '0' && ch <= '9')) {
      throw new ScannerError(
        'while scanning a directive', startMark,
        `expected a digit, but found ${charRepr(ch)}`, this.getMark()
      );
    }
    let length = 0;
    while (this.peek(length) >= '0' && this.peek(length) <= '9') length += 1;
    const value = Number(this.prefix(length));
    this.forward(length);
    return value;
  }

  scanTagDirectiveValue(startMark) {
    while (this.peek() === ' ') this.forward();
    const handle = this.scanTagDirectiveHandle(startMark);
    while (this.peek() === ' ') this.forward();
    const prefix = this.scanTagDirectivePrefix(startMark);
    return [handle, prefix];
  }

  scanTagDirectiveHandle(startMark) {
    const value = this.scanTagHandle('directive', startMark);
    if (this.peek() !== ' ') {
      throw new ScannerError(
        'while scanning a directive', startMark,
        `expected ' ', but found ${charRepr(this.peek())}`, this.getMark()
      );
    }
    return value;
  }

  scanTagDirectivePrefix(startMark) {
    const value = this.scanTagUri('directive', startMark);
    if (!inSet(this.peek(), NULL_BL_LINEBR)) {
      throw new ScannerError(
        'while scanning a directive', startMark,
        `expected ' ', but found ${charRepr(this.peek())}`, this.getMark()
      );
    }
    return value;
  }

  scanDirectiveIgnoredLine(startMark) {
    while (this.peek() === ' ') this.forward();
    if (this.peek() === '#') {
      while (!inSet(this.peek(), NULL_OR_LINEBR)) this.forward();
    }
    const ch = this.peek();
    if (!inSet(ch, NULL_OR_LINEBR)) {
      throw new ScannerError(
        'while scanning a directive', startMark,
        `expected a comment or a line break, but found ${charRepr(ch)}`, this.getMark()
      );
    }
    this.scanLineBreak();
  }

  scanAnchor(TokenClass) {
    const startMark = this.getMark();
    const indicator = this.peek();
    const name = indicator === '*' ? 'alias' : 'anchor';
    this.forward();
    let length = 0;
    let ch = this.peek(length);
    while (isNameChar(ch)) {
      length += 1;
      ch = this.peek(length);
    }
    if (length === 0) {
      throw new ScannerError(
        `while scanning an ${name}`, startMark,
        `expected alphabetic or numeric character, but found ${charRepr(ch)}`, this.getMark()
      );
    }
    const value = this.prefix(length);
    this.forward(length);
    ch = this.peek();
    if (!inSet(ch, NULL_BL_T_LINEBR + '?:,]}%@`')) {
      throw new ScannerError(
        `while scanning an ${name}`, startMark,
        `expected alphabetic or numeric character, but found ${charRepr(ch)}`, this.getMark()
      );
    }
    return new TokenClass(value, startMark, this.getMark());
  }

  scanTag() {
    const startMark = this.getMark();
    let ch = this.peek(1);
    let handle;
    let suffix;
    if (ch === '<') {
      handle = null;
      this.forward(2);
      suffix = this.scanTagUri('tag', startMark);
      if (this.peek() !== '>') {
        throw new ScannerError(
          'while parsing a tag', startMark,
          `expected '>', but found ${charRepr(this.peek())}`, this.getMark()
        );
      }
      this.forward();
    } else if (inSet(ch, NULL_BL_T_LINEBR)) {
      handle = null;
      suffix = '!';
      this.forward();
    } else {
      let length = 1;
      let useHandle = false;
      while (!inSet(ch, NULL_BL_LINEBR)) {
        if (ch === '!') {
          useHandle = true;
          break;
        }
        length += 1;
        ch = this.peek(length);
      }
      if (useHandle) {
        handle = this.scanTagHandle('tag', startMark);
      } else {
        handle = '!';
        this.forward();
      }
      suffix = this.scanTagUri('tag', startMark);
    }
    ch = this.peek();
    if (!inSet(ch, NULL_BL_LINEBR)) {
      throw new ScannerError(
        'while scanning a tag', startMark,
        `expected ' ', but found ${charRepr(ch)}`, this.getMark()
      );
    }
    return new TagToken([handle, suffix], startMark, this.getMark());
  }

  scanBlockScalar(style) {
    const folded = style === '>';
    const chunks = [];
    const startMark = this.getMark();

    this.forward();
    const [chomping, increment] = this.scanBlockScalarIndicators(startMark);
    this.scanBlockScalarIgnoredLine(startMark);

    let minIndent = this.indent + 1;
    if (minIndent < 1) minIndent = 1;
    let breaks;
    let indent;
    let endMark;
    if (increment === null) {
      const found = this.scanBlockScalarIndentation();
      breaks = found[0];
      indent = Math.max(minIndent, found[1]);
      endMark = found[2];
    } else {
      indent = minIndent + increment - 1;
      const found = this.scanBlockScalarBreaks(indent);
      breaks = found[0];
      endMark = found[1];
    }
    let lineBreak = '';

    while (this.column === indent && this.peek() !== '\0') {
      chunks.push(...breaks);
      const leadingNonSpace = this.peek() !== ' ' && this.peek() !== '\t';
      let length = 0;
      while (!inSet(this.peek(length), NULL_OR_LINEBR)) length += 1;
      chunks.push(this.prefix(length));
      this.forward(length);
      lineBreak = this.scanLineBreak();
      const found = this.scanBlockScalarBreaks(indent);
      breaks = found[0];
      endMark = found[1];
      if (this.column === indent && this.peek() !== '\0') {
        if (
          folded && lineBreak === '\n' && leadingNonSpace &&
          this.peek() !== ' ' && this.peek() !== '\t'
        ) {
          if (breaks.length === 0) chunks.push(' ');
        } else {
          chunks.push(lineBreak);
        }
      } else {
        break;
      }
    }

    if (chomping !== false) chunks.push(lineBreak);
    if (chomping === true) chunks.push(...breaks);

    return new ScalarToken(chunks.join(''), false, startMark, endMark, style);
  }

  scanBlockScalarIndicators(startMark) {
    let chomping = null;
    let increment = null;
    let ch = this.peek();
    if (ch === '+' || ch === '-') {
      chomping = ch === '+';
      this.forward();
      ch = this.peek();
      if (ch >= '0' && ch <= '9') {
        increment = Number(ch);
        if (increment === 0) {
          throw new ScannerError(
            'while scanning a block scalar', startMark,
            'expected indentation indicator in the range 1-9, but found 0', this.getMark()
          );
        }
        this.forward();
      }
    } else if (ch >= '0' && ch <= '9') {
      increment = Number(ch);
      if (increment === 0) {
        throw new ScannerError(
          'while scanning a block scalar', startMark,
          'expected indentation indicator in the range 1-9, but found 0', this.getMark()
        );
      }
      this.forward();
      ch = this.peek();
      if (ch === '+' || ch === '-') {
        chomping = ch === '+';
        this.forward();
      }
    }
    ch = this.peek();
    if (!inSet(ch, NULL_BL_LINEBR)) {
      throw new ScannerError(
        'while scanning a block scalar', startMark,
        `expected chomping or indentation indicators, but found ${charRepr(ch)}`, this.getMark()
      );
    }
    return [chomping, increment];
  }

  scanBlockScalarIgnoredLine(startMark) {
    while (this.peek() === ' ') this.forward();
    if (this.peek() === '#') {
      while (!inSet(this.peek(), NULL_OR_LINEBR)) this.forward();
    }
    const ch = this.peek();
    if (!inSet(ch, NULL_OR_LINEBR)) {
      throw new ScannerError(
        'while scanning a block scalar', startMark,
        `expected a comment or a line break, but found ${charRepr(ch)}`, this.getMark()
      );
    }
    this.scanLineBreak();
  }

  scanBlockScalarIndentation() {
    const chunks = [];
    let maxIndent = 0;
    let endMark = this.getMark();
    while (inSet(this.peek(), ' \r\n\x85  ')) {
      if (this.peek() !== ' ') {
        chunks.push(this.scanLineBreak());
        endMark = this.getMark();
      } else {
        this.forward();
        if (this.column > maxIndent) maxIndent = this.column;
      }
    }
    return [chunks, maxIndent, endMark];
  }

  scanBlockScalarBreaks(indent) {
    const chunks = [];
    let endMark = this.getMark();
    while (this.column < indent && this.peek() === ' ') this.forward();
    while (inSet(this.peek(), LINEBR)) {
      chunks.push(this.scanLineBreak());
      endMark = this.getMark();
      while (this.column < indent && this.peek() === ' ') this.forward();
    }
    return [chunks, endMark];
  }

  scanFlowScalar(style) {
    const double = style === '"';
    const chunks = [];
    const startMark = this.getMark();
    const quote = this.peek();
    this.forward();
    chunks.push(...this.scanFlowScalarNonSpaces(double, startMark));
    while (this.peek() !== quote) {
      chunks.push(...this.scanFlowScalarSpaces(double, startMark));
      chunks.push(...this.scanFlowScalarNonSpaces(double, startMark));
    }
    this.forward();
    return new ScalarToken(chunks.join(''), false, startMark, this.getMark(), style);
  }

  scanFlowScalarNonSpaces(double, startMark) {
    const ESCAPE_REPLACEMENTS = Scanner.ESCAPE_REPLACEMENTS;
    const ESCAPE_CODES = Scanner.ESCAPE_CODES;
    const chunks = [];
    for (;;) {
      let length = 0;
      while (!inSet(this.peek(length), '\'"\\\0 \t\r\n\x85  ')) length += 1;
      if (length > 0) {
        chunks.push(this.prefix(length));
        this.forward(length);
      }
      let ch = this.peek();
      if (!double && ch === "'" && this.peek(1) === "'") {
        chunks.push("'");
        this.forward(2);
      } else if ((double && ch === "'") || (!double && (ch === '"' || ch === '\\'))) {
        chunks.push(ch);
        this.forward();
      } else if (double && ch === '\\') {
        this.forward();
        ch = this.peek();
        if (Object.prototype.hasOwnProperty.call(ESCAPE_REPLACEMENTS, ch)) {
          chunks.push(ESCAPE_REPLACEMENTS[ch]);
          this.forward();
        } else if (Object.prototype.hasOwnProperty.call(ESCAPE_CODES, ch)) {
          const count = ESCAPE_CODES[ch];
          this.forward();
          for (let k = 0; k < count; k++) {
            if (!inSet(this.peek(k), HEXDIGITS)) {
              throw new ScannerError(
                'while scanning a double-quoted scalar', startMark,
                `expected escape sequence of ${count} hexdecimal numbers, but found ` +
                  `${charRepr(this.peek(k))}`,
                this.getMark()
              );
            }
          }
          const code = parseInt(this.prefix(count), 16);
          chunks.push(String.fromCodePoint(code));
          this.forward(count);
        } else if (inSet(ch, LINEBR)) {
          this.scanLineBreak();
          chunks.push(...this.scanFlowScalarBreaks(double, startMark));
        } else {
          throw new ScannerError(
            'while scanning a double-quoted scalar', startMark,
            `found unknown escape character ${charRepr(ch)}`, this.getMark()
          );
        }
      } else {
        return chunks;
      }
    }
  }

  scanFlowScalarSpaces(double, startMark) {
    const chunks = [];
    let length = 0;
    while (this.peek(length) === ' ' || this.peek(length) === '\t') length += 1;
    const whitespaces = this.prefix(length);
    this.forward(length);
    const ch = this.peek();
    if (ch === '\0') {
      throw new ScannerError(
        'while scanning a quoted scalar', startMark,
        'found unexpected end of stream', this.getMark()
      );
    } else if (inSet(ch, LINEBR)) {
      const lineBreak = this.scanLineBreak();
      const breaks = this.scanFlowScalarBreaks(double, startMark);
      if (lineBreak !== '\n') chunks.push(lineBreak);
      else if (breaks.length === 0) chunks.push(' ');
      chunks.push(...breaks);
    } else {
      chunks.push(whitespaces);
    }
    return chunks;
  }

  scanFlowScalarBreaks(double, startMark) {
    const chunks = [];
    for (;;) {
      const prefix = this.prefix(3);
      if ((prefix === '---' || prefix === '...') && inSet(this.peek(3), NULL_BL_T_LINEBR)) {
        throw new ScannerError(
          'while scanning a quoted scalar', startMark,
          'found unexpected document separator', this.getMark()
        );
      }
      while (this.peek() === ' ' || this.peek() === '\t') this.forward();
      if (inSet(this.peek(), LINEBR)) chunks.push(this.scanLineBreak());
      else return chunks;
    }
  }

  scanPlain() {
    const chunks = [];
    const startMark = this.getMark();
    let endMark = startMark;
    const indent = this.indent + 1;
    let spaces = [];
    for (;;) {
      if (this.peek() === '#') break;
      let length = 0;
      for (;;) {
        const ch = this.peek(length);
        if (
          inSet(ch, NULL_BL_T_LINEBR) ||
          (ch === ':' &&
            inSet(this.peek(length + 1), NULL_BL_T_LINEBR + (this.flowLevel ? ',[]{}' : ''))) ||
          (this.flowLevel && inSet(ch, ',?[]{}'))
        ) {
          break;
        }
        length += 1;
      }
      if (length === 0) break;
      this.allowSimpleKey = false;
      chunks.push(...spaces);
      chunks.push(this.prefix(length));
      this.forward(length);
      endMark = this.getMark();
      spaces = this.scanPlainSpaces(indent, startMark);
      if (
        spaces === null || spaces.length === 0 || this.peek() === '#' ||
        (!this.flowLevel && this.column < indent)
      ) {
        break;
      }
    }
    return new ScalarToken(chunks.join(''), true, startMark, endMark);
  }

  scanPlainSpaces() {
    const chunks = [];
    let length = 0;
    while (this.peek(length) === ' ') length += 1;
    const whitespaces = this.prefix(length);
    this.forward(length);
    const ch = this.peek();
    if (inSet(ch, LINEBR)) {
      const lineBreak = this.scanLineBreak();
      this.allowSimpleKey = true;
      let prefix = this.prefix(3);
      if ((prefix === '---' || prefix === '...') && inSet(this.peek(3), NULL_BL_T_LINEBR)) {
        return null;
      }
      const breaks = [];
      while (this.peek() === ' ' || inSet(this.peek(), LINEBR)) {
        if (this.peek() === ' ') {
          this.forward();
        } else {
          breaks.push(this.scanLineBreak());
          prefix = this.prefix(3);
          if ((prefix === '---' || prefix === '...') && inSet(this.peek(3), NULL_BL_T_LINEBR)) {
            return null;
          }
        }
      }
      if (lineBreak !== '\n') chunks.push(lineBreak);
      else if (breaks.length === 0) chunks.push(' ');
      chunks.push(...breaks);
    } else if (whitespaces.length > 0) {
      chunks.push(whitespaces);
    }
    return chunks;
  }

  scanTagHandle(name, startMark) {
    let ch = this.peek();
    if (ch !== '!') {
      throw new ScannerError(
        `while scanning a ${name}`, startMark,
        `expected '!', but found ${charRepr(ch)}`, this.getMark()
      );
    }
    let length = 1;
    ch = this.peek(length);
    if (ch !== ' ') {
      while (isNameChar(ch)) {
        length += 1;
        ch = this.peek(length);
      }
      if (ch !== '!') {
        this.forward(length);
        throw new ScannerError(
          `while scanning a ${name}`, startMark,
          `expected '!', but found ${charRepr(ch)}`, this.getMark()
        );
      }
      length += 1;
    }
    const value = this.prefix(length);
    this.forward(length);
    return value;
  }

  scanTagUri(name, startMark) {
    const URI_EXTRA = "-;/?:@&=+$,_.!~*'()[]%";
    const chunks = [];
    let length = 0;
    let ch = this.peek(length);
    while (
      (ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z') ||
      URI_EXTRA.indexOf(ch) !== -1
    ) {
      if (ch === '%') {
        chunks.push(this.prefix(length));
        this.forward(length);
        length = 0;
        chunks.push(this.scanUriEscapes(name, startMark));
      } else {
        length += 1;
      }
      ch = this.peek(length);
    }
    if (length > 0) {
      chunks.push(this.prefix(length));
      this.forward(length);
      length = 0;
    }
    if (chunks.length === 0) {
      throw new ScannerError(
        `while parsing a ${name}`, startMark,
        `expected URI, but found ${charRepr(ch)}`, this.getMark()
      );
    }
    return chunks.join('');
  }

  scanUriEscapes(name, startMark) {
    const codes = [];
    while (this.peek() === '%') {
      this.forward();
      for (let k = 0; k < 2; k++) {
        if (!inSet(this.peek(k), HEXDIGITS)) {
          throw new ScannerError(
            `while scanning a ${name}`, startMark,
            'expected URI escape sequence of 2 hexdecimal numbers, but found ' +
              `${charRepr(this.peek(k))}`,
            this.getMark()
          );
        }
      }
      codes.push(parseInt(this.prefix(2), 16));
      this.forward(2);
    }
    return Buffer.from(codes).toString('utf8');
  }

  scanLineBreak() {
    const ch = this.peek();
    if (ch === '\r' || ch === '\n' || ch === '\x85') {
      if (this.prefix(2) === '\r\n') this.forward(2);
      else this.forward();
      return '\n';
    }
    if (ch === ' ' || ch === ' ') {
      this.forward();
      return ch;
    }
    return '';
  }
}

Scanner.ESCAPE_REPLACEMENTS = {
  '0': '\0',
  a: '\x07',
  b: '\x08',
  t: '\x09',
  '\t': '\x09',
  n: '\x0A',
  v: '\x0B',
  f: '\x0C',
  r: '\x0D',
  e: '\x1B',
  ' ': '\x20',
  '"': '"',
  '\\': '\\',
  N: '\x85',
  _: '\xA0',
  L: ' ',
  P: ' ',
};

Scanner.ESCAPE_CODES = { x: 2, u: 4, U: 8 };

