// Character classification and string helpers.
//
// Every character set is spelled with explicit escapes: YAML treats U+0085,
// U+2028 and U+2029 as line breaks, and those are invisible in source.

/** Split a JS string into an array of code points (astral-safe). */
export function codePoints(text) {
  const out = [];
  for (const ch of text) out.push(ch);
  return out;
}

/** Repeat `ch` `n` times (n <= 0 yields ''). */
export function repeat(ch, n) {
  return n > 0 ? ch.repeat(n) : '';
}

/** Left-pad a decimal string with zeros up to `width`. */
export function zfill(text, width) {
  let s = text;
  let negative = false;
  if (s.startsWith('-')) {
    negative = true;
    s = s.slice(1);
  }
  const target = negative ? width - 1 : width;
  while (s.length < target) s = '0' + s;
  return (negative ? '-' : '') + s;
}

/** True when `text` contains `ch`; stands in for Python's `ch in str`. */
export function inSet(ch, text) {
  return ch !== undefined && ch.length > 0 && text.indexOf(ch) !== -1;
}

export const NUL = '�';
export const BOM = '﻿';
export const NEL = '';
export const LS = ' ';
export const PS = ' ';
export const NBSP = ' ';

/** Line-break characters. */
export const LINEBR = '\r\n' + NEL + LS + PS;
/** NUL + line breaks. */
export const NULL_OR_LINEBR = NUL + LINEBR;
/** NUL + blank + line breaks. */
export const NULL_BL_LINEBR = NUL + ' ' + LINEBR;
/** NUL + blank + tab + line breaks. */
export const NULL_BL_T_LINEBR = NUL + ' \t' + LINEBR;
/** Blanks and line breaks. */
export const BL_T_LINEBR = ' \t' + LINEBR;
