12	  BlockMappingStartToken, BlockSequenceStartToken, DirectiveToken,
13	  DocumentEndToken, DocumentStartToken, FlowEntryToken, FlowMappingEndToken,
14	  FlowMappingStartToken, FlowSequenceEndToken, FlowSequenceStartToken,
