24	/** Python's `repr()` for the single characters that appear in scanner errors. */
25	export function charRepr(ch) {
26	  const map = {
27	    '\\': '\\\\', "'": "\\'", '\n': '\\n', '\r': '\\r', '\t': '\\t',
28	    '\x07': '\\x07', '\x08': '\\x08', '\x0b': '\\x0b', '\x0c': '\\x0c',
29	    '\0': '\\x00', '\x1b': '\\x1b', '\x85': '\\x85',
30	  };
31	  if (map[ch] !== undefined) return "'" + map[ch] + "'";
32	  const code = ch.codePointAt(0);
33	  if (code < 0x20 || code === 0x7f) {
34	    return "'\\x" + code.toString(16).padStart(2, '0') + "'";
35	  }
36	  return "'" + ch + "'";
37	}
