50	export class Scanner extends Reader {
51	  initScanner() {
52	    this.done = false;
53	    this.flowLevel = 0;
54	    this.tokens = [];
55	    this.encoding = null;
56	    this.fetchStreamStart();
57	    this.tokensTaken = 0;
58	    this.indent = -1;
59	    this.indents = [];
60	    this.allowSimpleKey = true;
61	    this.possibleSimpleKeys = new Map();
62	  }
63	
64	  /** @param {Function[]} choices token classes; empty means "any token" */
65	  checkToken(...choices) {
66	    while (this.needMoreTokens()) this.fetchMoreTokens();
67	    if (this.tokens.length > 0) {
68	      if (choices.length === 0) return true;
69	      for (const choice of choices) {
