// Event parser. States are stored as method names so the state stack behaves
// like PyYAML's list of bound methods.

import { Scanner } from './scanner.mjs';
import { ParserError } from './errors.mjs';
import {
  AliasEvent, DocumentEndEvent, DocumentStartEvent, MappingEndEvent,
  MappingStartEvent, ScalarEvent, SequenceEndEvent, SequenceStartEvent,
  StreamEndEvent, StreamStartEvent,
} from './events.mjs';
import {
  AliasToken, AnchorToken, BlockEndToken, BlockEntryToken,
  BlockMappingStartToken, BlockSequenceStartToken, DirectiveToken,
  DocumentEndToken, DocumentStartToken, FlowEntryToken, FlowMappingEndToken,
  FlowMappingStartToken, FlowSequenceEndToken, FlowSequenceStartToken,
  KeyToken, ScalarToken, StreamEndToken, TagToken, ValueToken,
} from './tokens.mjs';

const DEFAULT_TAGS = { '!': '!', '!!': 'tag:yaml.org,2002:' };

export class Parser extends Scanner {
  initParser() {
    this.currentEvent = null;
    this.yamlVersion = null;
    this.tagHandles = {};
    this.states = [];
    this.marks = [];
    this.state = 'parseStreamStart';
  }

  /** Run the current state function, if any. */
  callState() {
    return this.state === null ? null : this[this.state]();
  }

  checkEvent(...choices) {
    if (this.currentEvent === null && this.state !== null) {
      this.currentEvent = this.callState();
    }
    if (this.currentEvent !== null) {
      if (choices.length === 0) return true;
      for (const choice of choices) {
        if (this.currentEvent instanceof choice) return true;
      }
    }
    return false;
  }

  peekEvent() {
    if (this.currentEvent === null && this.state !== null) {
      this.currentEvent = this.callState();
    }
    return this.currentEvent;
  }

  getEvent() {
    if (this.currentEvent === null && this.state !== null) {
      this.currentEvent = this.callState();
    }
    const value = this.currentEvent;
    this.currentEvent = null;
    return value;
  }

  /* -------------------------------------------------------------- */
  /* Stream / document                                               */
  /* -------------------------------------------------------------- */

  parseStreamStart() {
    const token = this.getToken();
    const event = new StreamStartEvent(token.startMark, token.endMark, token.encoding);
    this.state = 'parseImplicitDocumentStart';
    return event;
  }

  parseImplicitDocumentStart() {
    if (!this.checkToken(DirectiveToken, DocumentStartToken, StreamEndToken)) {
      this.tagHandles = { ...DEFAULT_TAGS };
      const token = this.peekToken();
      const event = new DocumentStartEvent(token.startMark, token.startMark, false);
      this.states.push('parseDocumentEnd');
      this.state = 'parseBlockNode';
      return event;
    }
    return this.parseDocumentStart();
  }

  parseDocumentStart() {
    while (this.checkToken(DocumentEndToken)) this.getToken();
    if (!this.checkToken(StreamEndToken)) {
      let token = this.peekToken();
      const startMark = token.startMark;
      const [version, tags] = this.processDirectives();
      if (!this.checkToken(DocumentStartToken)) {
        throw new ParserError(
          null, null,
          `expected '<document start>', but found ${pyRepr(this.peekToken().id)}`,
          this.peekToken().startMark
        );
      }
      token = this.getToken();
      const event = new DocumentStartEvent(startMark, token.endMark, true, version, tags);
      this.states.push('parseDocumentEnd');
      this.state = 'parseDocumentContent';
      return event;
    }
    const token = this.getToken();
    const event = new StreamEndEvent(token.startMark, token.endMark);
    this.state = null;
    return event;
  }

  parseDocumentEnd() {
    let token = this.peekToken();
    const startMark = token.startMark;
    let endMark = token.startMark;
    let explicit = false;
    if (this.checkToken(DocumentEndToken)) {
      token = this.getToken();
      endMark = token.endMark;
      explicit = true;
    }
    this.state = 'parseDocumentStart';
    return new DocumentEndEvent(startMark, endMark, explicit);
  }

  parseDocumentContent() {
    if (this.checkToken(DirectiveToken, DocumentStartToken, DocumentEndToken, StreamEndToken)) {
      const event = this.processEmptyScalar(this.peekToken().startMark);
      this.state = this.states.pop();
      return event;
    }
    return this.parseBlockNode();
  }

  processDirectives() {
    this.yamlVersion = null;
    this.tagHandles = {};
    while (this.checkToken(DirectiveToken)) {
      const token = this.getToken();
      if (token.name === 'YAML') {
        if (this.yamlVersion !== null) {
          throw new ParserError(null, null, 'found duplicate YAML directive', token.startMark);
        }
        const [major] = token.value;
        if (major !== 1) {
          throw new ParserError(
            null, null,
            'found incompatible YAML document (version 1.* is required)', token.startMark
          );
        }
        this.yamlVersion = token.value;
      } else if (token.name === 'TAG') {
        const [handle, prefix] = token.value;
        if (Object.prototype.hasOwnProperty.call(this.tagHandles, handle)) {
          throw new ParserError(
            null, null, `duplicate tag handle ${pyRepr(handle)}`, token.startMark
          );
        }
        this.tagHandles[handle] = prefix;
      }
    }
    const used = Object.keys(this.tagHandles).length > 0 ? { ...this.tagHandles } : null;
    for (const key of Object.keys(DEFAULT_TAGS)) {
      if (!Object.prototype.hasOwnProperty.call(this.tagHandles, key)) {
        this.tagHandles[key] = DEFAULT_TAGS[key];
      }
    }
    return [this.yamlVersion, used];
  }

  /* -------------------------------------------------------------- */
  /* Nodes                                                           */
  /* -------------------------------------------------------------- */

  parseBlockNode() {
    return this.parseNode(true, false);
  }

  parseFlowNode() {
    return this.parseNode(false, false);
  }

  parseBlockNodeOrIndentlessSequence() {
    return this.parseNode(true, true);
  }

  parseNode(block = false, indentlessSequence = false) {
    if (this.checkToken(AliasToken)) {
      const token = this.getToken();
      this.state = this.states.pop();
      return new AliasEvent(token.value, token.startMark, token.endMark);
    }

    let anchor = null;
    let tag = null;
    let startMark = null;
    let endMark = null;
    let tagMark = null;
    if (this.checkToken(AnchorToken)) {
      let token = this.getToken();
      startMark = token.startMark;
      endMark = token.endMark;
      anchor = token.value;
      if (this.checkToken(TagToken)) {
        token = this.getToken();
        tagMark = token.startMark;
        endMark = token.endMark;
