// Node composer: turns the event stream into a node graph and resolves anchors.

import { Parser, pyRepr } from './parser.mjs';
import { ComposerError } from './errors.mjs';
import {
  AliasEvent, MappingEndEvent, MappingNode, MappingStartEvent, ScalarEvent,
  ScalarNode, SequenceEndEvent, SequenceNode, SequenceStartEvent,
  StreamEndEvent, StreamStartEvent,
} from './events.mjs';

export class Composer extends Parser {
  initComposer() {
    this.anchors = new Map();
  }

  checkNode() {
    if (this.checkEvent(StreamStartEvent)) this.getEvent();
    return !this.checkEvent(StreamEndEvent);
  }

  getNode() {
    if (!this.checkEvent(StreamEndEvent)) return this.composeDocument();
    return null;
  }

  getSingleNode() {
    this.getEvent(); // drop STREAM-START
    let document = null;
    if (!this.checkEvent(StreamEndEvent)) document = this.composeDocument();
    if (!this.checkEvent(StreamEndEvent)) {
      const event = this.getEvent();
      throw new ComposerError(
        'expected a single document in the stream', document.startMark,
        'but found another document', event.startMark
      );
    }
    this.getEvent(); // drop STREAM-END
    return document;
  }

  composeDocument() {
    this.getEvent(); // drop DOCUMENT-START
    const node = this.composeNode(null, null);
    this.getEvent(); // drop DOCUMENT-END
    this.anchors = new Map();
    return node;
  }

  composeNode(parent, index) {
    if (this.checkEvent(AliasEvent)) {
      const event = this.getEvent();
      const anchor = event.anchor;
      if (!this.anchors.has(anchor)) {
        throw new ComposerError(
          null, null, `found undefined alias ${pyRepr(anchor)}`, event.startMark
        );
      }
      return this.anchors.get(anchor);
    }
    const event = this.peekEvent();
    const anchor = event.anchor;
    if (anchor !== null && this.anchors.has(anchor)) {
      throw new ComposerError(
        `found duplicate anchor ${pyRepr(anchor)}; first occurrence`,
        this.anchors.get(anchor).startMark, 'second occurrence', event.startMark
      );
    }
    this.descendResolver(parent, index);
    let node = null;
    if (this.checkEvent(ScalarEvent)) node = this.composeScalarNode(anchor);
    else if (this.checkEvent(SequenceStartEvent)) node = this.composeSequenceNode(anchor);
    else if (this.checkEvent(MappingStartEvent)) node = this.composeMappingNode(anchor);
    this.ascendResolver();
    return node;
  }

  composeScalarNode(anchor) {
    const event = this.getEvent();
    let tag = event.tag;
    if (tag === null || tag === '!') {
      tag = this.resolve(ScalarNode, event.value, event.implicit);
    }
    const node = new ScalarNode(tag, event.value, event.startMark, event.endMark, event.style);
    if (anchor !== null) this.anchors.set(anchor, node);
    return node;
  }

  composeSequenceNode(anchor) {
    const startEvent = this.getEvent();
    let tag = startEvent.tag;
    if (tag === null || tag === '!') {
      tag = this.resolve(SequenceNode, null, startEvent.implicit);
    }
    const node = new SequenceNode(tag, [], startEvent.startMark, null, startEvent.flowStyle);
    if (anchor !== null) this.anchors.set(anchor, node);
    let index = 0;
    while (!this.checkEvent(SequenceEndEvent)) {
      node.value.push(this.composeNode(node, index));
      index += 1;
    }
    node.endMark = this.getEvent().endMark;
    return node;
  }

  composeMappingNode(anchor) {
    const startEvent = this.getEvent();
    let tag = startEvent.tag;
    if (tag === null || tag === '!') {
      tag = this.resolve(MappingNode, null, startEvent.implicit);
    }
    const node = new MappingNode(tag, [], startEvent.startMark, null, startEvent.flowStyle);
    if (anchor !== null) this.anchors.set(anchor, node);
    while (!this.checkEvent(MappingEndEvent)) {
      const itemKey = this.composeNode(node, null);
      const itemValue = this.composeNode(node, itemKey);
      node.value.push([itemKey, itemValue]);
    }
    node.endMark = this.getEvent().endMark;
    return node;
  }
}

