// SafeConstructor: node graph -> Python values.
//
// PyYAML uses generator-based constructors so that recursive containers can be
// filled in after the placeholder is registered; JS generators map onto that
// directly.

import { Composer } from './composer.mjs';
import { ConstructorError, PythonError, valueError } from './errors.mjs';
import { MappingNode, ScalarNode, SequenceNode } from './events.mjs';
import { matchTimestamp } from './resolver.mjs';
import { base64Decode } from './base64.mjs';
import { parseFloat_, parseInt_ } from './pyfloat.mjs';
import {
  PyBytes, PyDate, PyDateTime, PyDict, PySet, PyTimezone, PyTuple, hashKey,
} from './pytypes.mjs';

const BOOL_VALUES = {
  yes: true, no: false, true: true, false: false, on: true, off: false,
};

function isGenerator(value) {
  return (
    value !== null && typeof value === 'object' &&
    typeof value.next === 'function' && typeof value[Symbol.iterator] === 'function'
  );
}

export class Constructor extends Composer {
  initConstructor() {
    this.constructedObjects = new Map();
    this.recursiveObjects = new Map();
    this.stateGenerators = [];
    this.deepConstruct = false;
  }

  getSingleData() {
    const node = this.getSingleNode();
    if (node !== null) return this.constructDocument(node);
    return null;
  }

  constructDocument(node) {
    const data = this.constructObject(node);
    while (this.stateGenerators.length > 0) {
      const generators = this.stateGenerators;
      this.stateGenerators = [];
      for (const generator of generators) {
        for (const _ of generator) { /* drain */ }
      }
    }
    this.constructedObjects = new Map();
    this.recursiveObjects = new Map();
    this.deepConstruct = false;
    return data;
  }

  constructObject(node, deep = false) {
    if (this.constructedObjects.has(node)) return this.constructedObjects.get(node);
    let oldDeep;
    if (deep) {
      oldDeep = this.deepConstruct;
      this.deepConstruct = true;
    }
    if (this.recursiveObjects.has(node)) {
      throw new ConstructorError(
        null, null, 'found unconstructable recursive node', node.startMark
      );
    }
    this.recursiveObjects.set(node, null);

    const constructor = CONSTRUCTORS[node.tag];
    let data;
    if (constructor !== undefined) {
      data = constructor.call(this, node);
    } else {
      data = this.constructUndefined(node);
    }
    if (isGenerator(data)) {
      const generator = data;
      data = generator.next().value;
      if (this.deepConstruct) {
        for (const _ of generator) { /* drain */ }
      } else {
        this.stateGenerators.push(generator);
      }
    }
    this.constructedObjects.set(node, data);
    this.recursiveObjects.delete(node);
    if (deep) this.deepConstruct = oldDeep;
    return data;
  }

  /* -------------------------------------------------------------- */
  /* Generic node readers                                            */
  /* -------------------------------------------------------------- */

  constructScalar(node) {
    if (node instanceof MappingNode) {
      for (const [keyNode, valueNode] of node.value) {
        if (keyNode.tag === 'tag:yaml.org,2002:value') return this.constructScalar(valueNode);
      }
    }
    if (!(node instanceof ScalarNode)) {
      throw new ConstructorError(
        null, null, `expected a scalar node, but found ${node.id}`, node.startMark
      );
    }
    return node.value;
  }

  constructSequence(node, deep = false) {
    if (!(node instanceof SequenceNode)) {
      throw new ConstructorError(
        null, null, `expected a sequence node, but found ${node.id}`, node.startMark
      );
    }
    return node.value.map((child) => this.constructObject(child, deep));
  }

  constructMapping(node, deep = false) {
    if (node instanceof MappingNode) this.flattenMapping(node);
    if (!(node instanceof MappingNode)) {
      throw new ConstructorError(
        null, null, `expected a mapping node, but found ${node.id}`, node.startMark
      );
    }
    const mapping = new PyDict();
    for (const [keyNode, valueNode] of node.value) {
      const key = this.constructObject(keyNode, deep);
      try {
        hashKey(key);
      } catch {
        throw new ConstructorError(
          'while constructing a mapping', node.startMark, 'found unhashable key',
          keyNode.startMark
        );
      }
      const value = this.constructObject(valueNode, deep);
      mapping.set(key, value);
    }
    return mapping;
  }

  constructPairs(node, deep = false) {
    if (!(node instanceof MappingNode)) {
      throw new ConstructorError(
        null, null, `expected a mapping node, but found ${node.id}`, node.startMark
      );
    }
    return node.value.map(([keyNode, valueNode]) => new PyTuple([
      this.constructObject(keyNode, deep),
      this.constructObject(valueNode, deep),
    ]));
  }

  /** Expand `<<` merge keys in place, exactly as SafeConstructor does. */
  flattenMapping(node) {
    let merge = [];
    let index = 0;
    while (index < node.value.length) {
      const [keyNode, valueNode] = node.value[index];
      if (keyNode.tag === 'tag:yaml.org,2002:merge') {
        node.value.splice(index, 1);
        if (valueNode instanceof MappingNode) {
          this.flattenMapping(valueNode);
          merge = merge.concat(valueNode.value);
        } else if (valueNode instanceof SequenceNode) {
          const submerge = [];
          for (const subnode of valueNode.value) {
            if (!(subnode instanceof MappingNode)) {
              throw new ConstructorError(
                'while constructing a mapping', node.startMark,
                `expected a mapping for merging, but found ${subnode.id}`, subnode.startMark
              );
            }
            this.flattenMapping(subnode);
            submerge.push(subnode.value);
          }
          submerge.reverse();
          for (const value of submerge) merge = merge.concat(value);
        } else {
          throw new ConstructorError(
            'while constructing a mapping', node.startMark,
            'expected a mapping or list of mappings for merging, but found ' +
              `${valueNode.id}`,
            valueNode.startMark
          );
        }
      } else if (keyNode.tag === 'tag:yaml.org,2002:value') {
        keyNode.tag = 'tag:yaml.org,2002:str';
        index += 1;
      } else {
        index += 1;
      }
    }
    if (merge.length > 0) node.value = merge.concat(node.value);
  }

  /* -------------------------------------------------------------- */
  /* Tag constructors                                                */
  /* -------------------------------------------------------------- */

  constructYamlNull(node) {
    this.constructScalar(node);
    return null;
  }

  constructYamlBool(node) {
    const value = this.constructScalar(node);
    const found = BOOL_VALUES[value.toLowerCase()];
    if (found === undefined) throw new PythonError('KeyError', pyKeyRepr(value));
    return found;
  }

  constructYamlInt(node) {
    let value = this.constructScalar(node).split('_').join('');
    let sign = 1n;
    if (value[0] === '-') sign = -1n;
    if (value[0] === '+' || value[0] === '-') value = value.slice(1);
    if (value === '0') return 0n;
    if (value.startsWith('0b')) return sign * parseInt_(value.slice(2), 2);
    if (value.startsWith('0x')) return sign * parseInt_(value.slice(2), 16);
    if (value[0] === '0') return sign * parseInt_(value, 8);
    if (value.indexOf(':') !== -1) {
      const digits = value.split(':').map((part) => parseInt_(part, 10)).reverse();
      let base = 1n;
      let total = 0n;
      for (const digit of digits) {
        total += digit * base;
        base *= 60n;
      }
      return sign * total;
    }
    return sign * parseInt_(value, 10);
  }

  constructYamlFloat(node) {
    let value = this.constructScalar(node).split('_').join('').toLowerCase();
    let sign = 1;
    if (value[0] === '-') sign = -1;
    if (value[0] === '+' || value[0] === '-') value = value.slice(1);
    if (value === '.inf') return sign * Infinity;
    if (value === '.nan') return NaN;
    if (value.indexOf(':') !== -1) {
      const digits = value.split(':').map((part) => parseFloat_(part)).reverse();
      let base = 1;
      let total = 0;
      for (const digit of digits) {
        total += digit * base;
        base *= 60;
      }
      return sign * total;
    }
    return sign * parseFloat_(value);
  }

  constructYamlBinary(node) {
    const value = this.constructScalar(node);
    for (const ch of value) {
      if (ch.codePointAt(0) > 0x7f) {
        throw new ConstructorError(
          null, null,
          'failed to convert base64 data into ascii: ' +
            "'ascii' codec can't encode character",
          node.startMark
        );
      }
    }
    try {
      return new PyBytes(base64Decode(value));
    } catch (err) {
      throw new ConstructorError(
        null, null, `failed to decode base64 data: ${err.message}`, node.startMark
      );
    }
  }

  constructYamlTimestamp(node) {
    const value = this.constructScalar(node);
    const groups = matchTimestamp(value);
    if (groups === null) {
      throw new PythonError('AttributeError', "'NoneType' object has no attribute 'groupdict'");
    }
    const year = Number(groups.year);
    const month = Number(groups.month);
    const day = Number(groups.day);
    if (groups.hour === null) return new PyDate(year, month, day);
    const hour = Number(groups.hour);
    const minute = Number(groups.minute);
    const second = Number(groups.second);
    let fraction = 0;
    if (groups.fraction) {
      let digits = groups.fraction.slice(0, 6);
      while (digits.length < 6) digits += '0';
      fraction = Number(digits);
    }
    let tzinfo = null;
    if (groups.tzSign) {
      const tzHour = Number(groups.tzHour);
      const tzMinute = Number(groups.tzMinute ?? 0);
      let minutes = tzHour * 60 + tzMinute;
      if (groups.tzSign === '-') minutes = -minutes;
      tzinfo = new PyTimezone(minutes);
    } else if (groups.tz) {
      tzinfo = PyTimezone.utc();
    }
    return new PyDateTime(year, month, day, hour, minute, second, fraction, tzinfo);
  }

  *constructYamlOmap(node) {
    const omap = [];
    yield omap;
    if (!(node instanceof SequenceNode)) {
      throw new ConstructorError(
        'while constructing an ordered map', node.startMark,
        `expected a sequence, but found ${node.id}`, node.startMark
      );
    }
    for (const subnode of node.value) {
      if (!(subnode instanceof MappingNode)) {
        throw new ConstructorError(
          'while constructing an ordered map', node.startMark,
          `expected a mapping of length 1, but found ${subnode.id}`, subnode.startMark
        );
      }
      if (subnode.value.length !== 1) {
        throw new ConstructorError(
          'while constructing an ordered map', node.startMark,
          `expected a single mapping item, but found ${subnode.value.length} items`,
          subnode.startMark
        );
      }
      const [keyNode, valueNode] = subnode.value[0];
      omap.push(new PyTuple([
        this.constructObject(keyNode), this.constructObject(valueNode),
      ]));
    }
  }

  *constructYamlPairs(node) {
    const pairs = [];
    yield pairs;
    if (!(node instanceof SequenceNode)) {
      throw new ConstructorError(
        'while constructing pairs', node.startMark,
        `expected a sequence, but found ${node.id}`, node.startMark
      );
    }
    for (const subnode of node.value) {
      if (!(subnode instanceof MappingNode)) {
        throw new ConstructorError(
          'while constructing pairs', node.startMark,
          `expected a mapping of length 1, but found ${subnode.id}`, subnode.startMark
        );
      }
      if (subnode.value.length !== 1) {
        throw new ConstructorError(
          'while constructing pairs', node.startMark,
          `expected a single mapping item, but found ${subnode.value.length} items`,
          subnode.startMark
        );
      }
      const [keyNode, valueNode] = subnode.value[0];
      pairs.push(new PyTuple([
        this.constructObject(keyNode), this.constructObject(valueNode),
      ]));
    }
  }

  *constructYamlSet(node) {
    const data = new PySet();
    yield data;
    const value = this.constructMapping(node);
    for (const key of value.keys()) data.add(key);
  }

  constructYamlStr(node) {
    return this.constructScalar(node);
  }

  *constructYamlSeq(node) {
    const data = [];
    yield data;
    data.push(...this.constructSequence(node));
  }

  *constructYamlMap(node) {
    const data = new PyDict();
    yield data;
    data.update(this.constructMapping(node));
  }

  constructUndefined(node) {
    throw new ConstructorError(
      null, null,
      `could not determine a constructor for the tag ${pyKeyRepr(node.tag)}`, node.startMark
    );
  }
}

/** Python `repr()` of a string, as used in KeyError / ConstructorError text. */
function pyKeyRepr(text) {
  return "'" + text.split('\\').join('\\\\').split("'").join("\\'") + "'";
}

const CONSTRUCTORS = {
  'tag:yaml.org,2002:null': Constructor.prototype.constructYamlNull,
  'tag:yaml.org,2002:bool': Constructor.prototype.constructYamlBool,
  'tag:yaml.org,2002:int': Constructor.prototype.constructYamlInt,
  'tag:yaml.org,2002:float': Constructor.prototype.constructYamlFloat,
  'tag:yaml.org,2002:binary': Constructor.prototype.constructYamlBinary,
  'tag:yaml.org,2002:timestamp': Constructor.prototype.constructYamlTimestamp,
  'tag:yaml.org,2002:omap': Constructor.prototype.constructYamlOmap,
  'tag:yaml.org,2002:pairs': Constructor.prototype.constructYamlPairs,
  'tag:yaml.org,2002:set': Constructor.prototype.constructYamlSet,
  'tag:yaml.org,2002:str': Constructor.prototype.constructYamlStr,
  'tag:yaml.org,2002:seq': Constructor.prototype.constructYamlSeq,
  'tag:yaml.org,2002:map': Constructor.prototype.constructYamlMap,
};

export { valueError };

