// Representer: Python values -> node graph. Matches `yaml.Dumper`, i.e. the
// full (non-safe) Representer, which is what `yaml.dump` uses.

import { MappingNode, ScalarNode, SequenceNode } from './events.mjs';
import { RepresenterError } from './errors.mjs';
import { base64Encode } from './base64.mjs';
import { floatRepr } from './pyfloat.mjs';
import {
  PyBytes, PyDate, PyDateTime, PyDict, PySet, PyTuple, pyLess, pySorted,
} from './pytypes.mjs';
import { Serializer } from './serializer.mjs';

/** Values PyYAML never aliases: None, empty tuple, str, bytes, bool, int, float. */
function ignoreAliases(data) {
  if (data === null) return true;
  if (data instanceof PyTuple && data.items.length === 0) return true;
  const t = typeof data;
  if (t === 'string' || t === 'boolean' || t === 'bigint' || t === 'number') return true;
  if (data instanceof PyBytes) return true;
  return false;
}

export class Representer extends Serializer {
  initRepresenter(defaultStyle = null, defaultFlowStyle = false, sortKeys = true) {
    this.defaultStyle = defaultStyle;
    this.defaultFlowStyle = defaultFlowStyle;
    this.sortKeys = sortKeys;
    this.representedObjects = new Map();
    this.objectKeeper = [];
    this.aliasKey = null;
  }

  represent(data) {
    const node = this.representData(data);
    this.serialize(node);
    this.representedObjects = new Map();
    this.objectKeeper = [];
    this.aliasKey = null;
  }

  representData(data) {
    this.aliasKey = ignoreAliases(data) ? null : data;
    if (this.aliasKey !== null) {
      if (this.representedObjects.has(this.aliasKey)) {
        return this.representedObjects.get(this.aliasKey);
      }
      this.objectKeeper.push(data);
    }
    return this.dispatch(data);
  }

  dispatch(data) {
    if (data === null) return this.representNone(data);
    switch (typeof data) {
      case 'string':
        return this.representStr(data);
      case 'boolean':
        return this.representBool(data);
      case 'bigint':
        return this.representInt(data);
      case 'number':
        return this.representFloat(data);
      default:
        break;
    }
    if (data instanceof PyBytes) return this.representBinary(data);
    if (Array.isArray(data)) return this.representList(data);
    if (data instanceof PyTuple) return this.representTuple(data);
    if (data instanceof PyDict) return this.representDict(data);
    if (data instanceof PySet) return this.representSet(data);
    if (data instanceof PyDateTime) return this.representDatetime(data);
    if (data instanceof PyDate) return this.representDate(data);
    throw new RepresenterError('cannot represent an object');
  }

  representScalar(tag, value, style = null) {
    const node = new ScalarNode(tag, value, null, null, style ?? this.defaultStyle);
    if (this.aliasKey !== null) this.representedObjects.set(this.aliasKey, node);
    return node;
  }

  representSequence(tag, sequence, flowStyle = null) {
    const value = [];
    const node = new SequenceNode(tag, value, null, null, flowStyle);
    if (this.aliasKey !== null) this.representedObjects.set(this.aliasKey, node);
    let bestStyle = true;
    for (const item of sequence) {
      const nodeItem = this.representData(item);
      if (!(nodeItem instanceof ScalarNode && !nodeItem.style)) bestStyle = false;
      value.push(nodeItem);
    }
    if (flowStyle === null) {
      node.flowStyle = this.defaultFlowStyle !== null ? this.defaultFlowStyle : bestStyle;
    }
    return node;
  }

  representMapping(tag, mapping, flowStyle = null) {
    const value = [];
    const node = new MappingNode(tag, value, null, null, flowStyle);
    if (this.aliasKey !== null) this.representedObjects.set(this.aliasKey, node);
    let bestStyle = true;
    let items = mapping.items();
    if (this.sortKeys) {
      try {
        // sorted() over (key, value) tuples: keys decide, and a dict cannot
        // hold two equal keys, so values never break the tie.
        items = pySorted(items, (a, b) => pyLess(a[0], b[0]));
      } catch {
        // Mixed key types are unorderable in Python 3; keep insertion order.
      }
    }
    for (const [itemKey, itemValue] of items) {
      const nodeKey = this.representData(itemKey);
      const nodeValue = this.representData(itemValue);
      if (!(nodeKey instanceof ScalarNode && !nodeKey.style)) bestStyle = false;
      if (!(nodeValue instanceof ScalarNode && !nodeValue.style)) bestStyle = false;
      value.push([nodeKey, nodeValue]);
    }
    if (flowStyle === null) {
      node.flowStyle = this.defaultFlowStyle !== null ? this.defaultFlowStyle : bestStyle;
    }
    return node;
  }

  /* -------------------------------------------------------------- */
  /* Per-type representers                                           */
  /* -------------------------------------------------------------- */

  representNone() {
    return this.representScalar('tag:yaml.org,2002:null', 'null');
  }

  representStr(data) {
    return this.representScalar('tag:yaml.org,2002:str', data);
  }

  representBinary(data) {
    return this.representScalar(
      'tag:yaml.org,2002:binary', base64Encode(data.bytes), '|'
    );
  }

  representBool(data) {
    return this.representScalar('tag:yaml.org,2002:bool', data ? 'true' : 'false');
  }

  representInt(data) {
    return this.representScalar('tag:yaml.org,2002:int', data.toString());
  }

  representFloat(data) {
    let value;
    if (Number.isNaN(data)) value = '.nan';
    else if (data === Infinity) value = '.inf';
    else if (data === -Infinity) value = '-.inf';
    else {
      value = floatRepr(data).toLowerCase();
      if (value.indexOf('.') === -1 && value.indexOf('e') !== -1) {
        value = value.replace('e', '.0e');
      }
    }
    return this.representScalar('tag:yaml.org,2002:float', value);
  }

  representList(data) {
    return this.representSequence('tag:yaml.org,2002:seq', data);
  }

  representTuple(data) {
    return this.representSequence('tag:yaml.org,2002:python/tuple', data.items);
  }

  representDict(data) {
    return this.representMapping('tag:yaml.org,2002:map', data);
  }

  representSet(data) {
    const value = new PyDict();
    for (const key of data.keys()) value.set(key, null);
    return this.representMapping('tag:yaml.org,2002:set', value);
  }

  representDate(data) {
    return this.representScalar('tag:yaml.org,2002:timestamp', data.isoformat());
  }

  representDatetime(data) {
    return this.representScalar('tag:yaml.org,2002:timestamp', data.isoformat(' '));
  }
}

