// Scalar analysis: decides which of the five scalar styles may be used.
// Ported from PyYAML's Emitter.analyze_scalar.

import {
  BOM, FULL_LINEBR, inSet, isAsciiPrintable, isEmittableUnicode, NULL_BL_T_LINEBR,
} from './chars.mjs';

export class ScalarAnalysis {
  constructor(scalar, empty, multiline, allowFlowPlain, allowBlockPlain,
    allowSingleQuoted, allowDoubleQuoted, allowBlock) {
    this.scalar = scalar;
    this.empty = empty;
    this.multiline = multiline;
    this.allowFlowPlain = allowFlowPlain;
    this.allowBlockPlain = allowBlockPlain;
    this.allowSingleQuoted = allowSingleQuoted;
    this.allowDoubleQuoted = allowDoubleQuoted;
    this.allowBlock = allowBlock;
  }
}

const LEADING_SPECIALS = '#,[]{}&*!|>\'"%@`';

/**
 * @param {string[]} scalar   scalar text as code points
 * @param {boolean} allowUnicode
 */
export function analyzeScalar(scalar, allowUnicode) {
  if (scalar.length === 0) {
    return new ScalarAnalysis(scalar, true, false, false, true, true, true, false);
  }

  let blockIndicators = false;
  let flowIndicators = false;
  let lineBreaks = false;
  let specialCharacters = false;

  let leadingSpace = false;
  let leadingBreak = false;
  let trailingSpace = false;
  let trailingBreak = false;
  let breakSpace = false;
  let spaceBreak = false;

  const head3 = scalar.slice(0, 3).join('');
  if (head3 === '---' || head3 === '...') {
    blockIndicators = true;
    flowIndicators = true;
  }

  let precededByWhitespace = true;
  let followedByWhitespace = scalar.length === 1 || inSet(scalar[1], NULL_BL_T_LINEBR);
  let previousSpace = false;
  let previousBreak = false;

  let index = 0;
  while (index < scalar.length) {
    const ch = scalar[index];

    if (index === 0) {
      if (LEADING_SPECIALS.indexOf(ch) !== -1) {
        flowIndicators = true;
        blockIndicators = true;
      }
      if (ch === '?' || ch === ':') {
        flowIndicators = true;
        if (followedByWhitespace) blockIndicators = true;
      }
      if (ch === '-' && followedByWhitespace) {
        flowIndicators = true;
        blockIndicators = true;
      }
    } else {
      if (',?[]{}'.indexOf(ch) !== -1) flowIndicators = true;
      if (ch === ':') {
        flowIndicators = true;
        if (followedByWhitespace) blockIndicators = true;
      }
      if (ch === '#' && precededByWhitespace) {
        flowIndicators = true;
        blockIndicators = true;
      }
    }

    if (inSet(ch, FULL_LINEBR)) lineBreaks = true;
    if (!(ch === '\n' || isAsciiPrintable(ch))) {
      if (isEmittableUnicode(ch)) {
        if (!allowUnicode) specialCharacters = true;
      } else {
        specialCharacters = true;
      }
    }

    if (ch === ' ') {
      if (index === 0) leadingSpace = true;
      if (index === scalar.length - 1) trailingSpace = true;
      if (previousBreak) breakSpace = true;
      previousSpace = true;
      previousBreak = false;
    } else if (inSet(ch, FULL_LINEBR)) {
      if (index === 0) leadingBreak = true;
      if (index === scalar.length - 1) trailingBreak = true;
      if (previousSpace) spaceBreak = true;
      previousSpace = false;
      previousBreak = true;
    } else {
      previousSpace = false;
      previousBreak = false;
    }

    index += 1;
    precededByWhitespace = inSet(ch, NULL_BL_T_LINEBR);
    followedByWhitespace =
      index + 1 >= scalar.length || inSet(scalar[index + 1], NULL_BL_T_LINEBR);
  }

  let allowFlowPlain = true;
  let allowBlockPlain = true;
  let allowSingleQuoted = true;
  const allowDoubleQuoted = true;
  let allowBlock = true;

  if (leadingSpace || leadingBreak || trailingSpace || trailingBreak) {
    allowFlowPlain = false;
    allowBlockPlain = false;
  }
  if (trailingSpace) allowBlock = false;
  if (breakSpace) {
    allowFlowPlain = false;
    allowBlockPlain = false;
    allowSingleQuoted = false;
  }
  if (spaceBreak || specialCharacters) {
    allowFlowPlain = false;
    allowBlockPlain = false;
    allowSingleQuoted = false;
    allowBlock = false;
  }
  if (lineBreaks) {
    allowFlowPlain = false;
    allowBlockPlain = false;
  }
  if (flowIndicators) allowFlowPlain = false;
  if (blockIndicators) allowBlockPlain = false;

  return new ScalarAnalysis(
    scalar, false, lineBreaks, allowFlowPlain, allowBlockPlain,
    allowSingleQuoted, allowDoubleQuoted, allowBlock
  );
}

export { BOM };

